img.script:
    // Static build (deploy/index.html from build-static.js, or opened from file://): there is no
    // server.js. Accounts and settings stay in localStorage, Games reads the catalog straight
    // from GitHub, AI Chat calls Pollinations, and apps that need the server are hidden.
    const STATIC = !!window.GHETTO_STATIC || location.protocol === "file:";

    // ======================= Settings (stored in this browser) =======================
    const DEFAULTS = {
      // v2 + libcurl passed every site tested (Poki games, YouTube, Google, Wikipedia).
      // v1 fails Poki's game check; Epoxy hits an HTTP/2 reset on YouTube.
      engine: "v2",          // "v2" = Scramjet 2.0.67-alpha.1, "v1" = Scramjet 1.1.0
      transport: "libcurl",  // "libcurl" | "epoxy"
      wisp: "",              // empty = this server's /wisp/
      search: "brave",
      searchCustom: "",      // template with %s
      cloak: "none",         // disguise preset id (CLOAKS) or "none"
      cloakTitle: "",        // overrides the preset's title when set
      cloakIcon: "",         // overrides the preset's icon when set
      blurCloak: false,      // cover the page with another site while unfocused
      blurSite: "khan",      // CLOAKS id shown by the cover
      panicKey: "",
      panicUrl: "https://classroom.google.com",
      panicBlank: true,      // the redirect key also reopens GhettoOS in an about:blank tab
      adblock: true,         // sw.js blocks ad/tracker hosts; pop-up tabs blocked in proxied pages
      theme: "nebula",       // THEMES key (wallpaper)
      animBg: "none",        // "none" | "aurora" | "stars" | "lava"
      layout: "classic",     // "classic" | "compact" dock icons
      lockOnStart: true,     // show the lock screen when GhettoOS opens
      userName: "",          // shown in the menu bar; typed on the lock screen
    };
    const SETTINGS_REV = 2; // bump to reset saved proxy choices when the recommended defaults change
    const DESIGN_REV = 1;   // bump to reset saved wallpaper choices when the look changes
    const settings = (() => {
      try {
        const saved = JSON.parse(localStorage.getItem("proxyos-settings") || "{}");
        if (saved._rev !== SETTINGS_REV) { delete saved.engine; delete saved.transport; }
        if (saved._design !== DESIGN_REV) { delete saved.theme; delete saved.animBg; }
        return { ...DEFAULTS, ...saved, _rev: SETTINGS_REV, _design: DESIGN_REV };
      } catch { return { ...DEFAULTS, _rev: SETTINGS_REV, _design: DESIGN_REV }; }
    })();
    // Signed-in username (null = guest) and listeners for when it changes. See "Accounts".
    let account = null, syncTimer = 0;
    const onAccountChange = new Set();
    function saveSettings() {
      try { localStorage.setItem("proxyos-settings", JSON.stringify(settings)); } catch {}
      queueSync(); // signed in: also saved to the account (see "Accounts")
    }

    const SEARCH_ENGINES = {
      brave: { name: "Brave Search", url: "https://search.brave.com/search?q=%s" },
      duckduckgo: { name: "DuckDuckGo", url: "https://duckduckgo.com/?q=%s" },
      google: { name: "Google", url: "https://www.google.com/search?q=%s" },
      bing: { name: "Bing", url: "https://www.bing.com/search?q=%s" },
      startpage: { name: "Startpage", url: "https://www.startpage.com/do/search?q=%s" },
      custom: { name: "Custom…", url: null },
    };

    // ======================= Proxy engines =======================
    const ENGINES = {
      v2: { name: "Scramjet v2 (2.0.67-alpha.1) — recommended" },
      v1: { name: "Scramjet v1 (1.1.0) — fallback" },
    };
    const TRANSPORTS = { libcurl: "libcurl (recommended)", epoxy: "Epoxy" };
    const ownWisp = (location.protocol === "https:" ? "wss://" : "ws://") + location.host + "/wisp/";
    const wispUrl = () => settings.wisp.trim() || ownWisp;

    function loadScript(src) {
      return new Promise((resolve, reject) => {
        const s = document.createElement("script");
        s.src = src;
        s.onload = resolve;
        s.onerror = () => reject(new Error("failed to load " + src));
        document.head.append(s);
      });
    }

    // Register /sw.js for the chosen engine and wait until that exact worker is active.
    async function registerSW(engine) {
      const url = "/sw.js?engine=" + engine;
      const reg = await navigator.serviceWorker.register(url);
      const want = new URL(url, location.href).href;
      const isWanted = () => reg.active && reg.active.scriptURL === want;
      if (!isWanted()) {
        await new Promise((resolve) => {
          const check = () => { if (isWanted()) resolve(); };
          reg.addEventListener("updatefound", () => reg.installing?.addEventListener("statechange", check));
          navigator.serviceWorker.addEventListener("controllerchange", check);
          const t = setInterval(() => { check(); if (isWanted()) clearInterval(t); }, 200);
        });
      }
      return reg;
    }

    // Each engine returns { attach(iframe) -> { go(url), current() } }.
    async function initV1() {
      await loadScript("/baremux/index.js");
      await loadScript("/scram/scramjet.all.js");
      const PREFIX = "/go/";
      const { ScramjetController } = $scramjetLoadController();
      const scramjet = new ScramjetController({
        files: { all: "/scram/scramjet.all.js", wasm: "/scram/scramjet.wasm.wasm", sync: "/scram/scramjet.sync.js" },
        prefix: PREFIX,
      });
      scramjet.init(); // must run before the SW handles requests (it creates the config DB)
      await registerSW("v1");
      const connection = new BareMux.BareMuxConnection("/baremux/worker.js");
      if (settings.transport === "libcurl") await connection.setTransport("/libcurl/index.mjs", [{ websocket: wispUrl() }]);
      else await connection.setTransport("/epoxy/index.mjs", [{ wisp: wispUrl() }]);
      return {
        attach(iframe) {
          return {
            go: (url) => (iframe.src = PREFIX + encodeURIComponent(url)), // scramjet.prefix + encodeURIComponent(url)
            current() {
              const p = iframe.contentWindow.location.pathname;
              return p.startsWith(PREFIX) ? decodeURIComponent(p.slice(PREFIX.length)) : null;
            },
          };
        },
      };
    }

    async function initV2() {
      await loadScript("/scramjet/scramjet.js");
      await loadScript("/controller/controller.api.js");
      const reg = await registerSW("v2");
      const { Controller } = $scramjetController;
      const { defaultConfig } = $scramjet;
      let transport;
      if (settings.transport === "libcurl") {
        const { default: LibcurlClient } = await import("/libcurl2/index.mjs"); // libcurl-transport 2.0.6
        transport = new LibcurlClient({ wisp: wispUrl() });
      } else {
        await loadScript("/epoxy3/index.js"); // epoxy-transport 3.0.1
        transport = new self.EpoxyTransport.default({ wisp: wispUrl() });
      }
      await transport.init();
      const controller = new Controller({ serviceworker: reg.active, transport, scramjetConfig: defaultConfig });
      await controller.wait();
      return {
        attach(iframe) {
          const frame = controller.createFrame(iframe);
          return {
            go: (url) => frame.go(url),
            current() {
              const p = iframe.contentWindow.location.pathname;
              const pre = new URL(frame.prefix, location.href).pathname;
              return p.startsWith(pre) ? decodeURIComponent(p.slice(pre.length)) : null;
            },
          };
        },
      };
    }

    const proxyReady = STATIC
      ? Promise.reject(new Error("The web browser needs the GhettoOS server."))
      : (settings.engine === "v2" ? initV2() : initV1()).catch((e) => {
        console.error("proxy init failed", e);
        throw e;
      });
    proxyReady.catch(() => {}); // handled where it's used

    function toUrl(input) {
      input = input.trim();
      if (/^https?:\/\//i.test(input)) return input;
      if (input.includes(".") && !input.includes(" ")) return "https://" + input;
      const tpl = settings.search === "custom" ? settings.searchCustom : SEARCH_ENGINES[settings.search]?.url;
      return (tpl && tpl.includes("%s") ? tpl : SEARCH_ENGINES.brave.url).replace("%s", encodeURIComponent(input));
    }

    // ======================= Windows =======================
    // Every window belongs to an app (its dock icon). Minimized windows are hidden (CSS) and
    // come back from the dock; the menu bar shows the focused window's app.
    const openWindows = new Set(); // { app, win }
    const MENU_H = 30;
    const dockSpace = () => (settings.layout === "compact" ? 40 : 52) + 26;
    function openWindow(title, el, opts = {}) {
      const { app = title, onclose: closed, ...rest } = opts;
      const rec = { app, win: null };
      openWindows.add(rec);
      rec.win = new WinBox(title, {
        mount: el, width: "70%", height: "70%", x: "center", y: "center", top: MENU_H, bottom: dockSpace(), ...rest,
        onfocus: () => setActiveApp(app),
        onminimize: () => { refreshDock(); setActiveApp(frontApp()); },
        onrestore: () => refreshDock(),
        onclose: () => { openWindows.delete(rec); closed?.(); refreshDock(); setActiveApp(frontApp()); },
      });
      refreshDock();
      return rec.win;
    }
    // App of the top-most visible window (WinBox raises z-index on focus).
    function frontApp() {
      let best = null, z = -1;
      for (const r of openWindows) {
        const zi = +r.win.window.style.zIndex || 0;
        if (!r.win.min && zi > z) { z = zi; best = r.app; }
      }
      return best || "Desktop";
    }
    function setActiveApp(name) { document.getElementById("mb-app").textContent = name; }

    // ======================= Browser app =======================
    // With `app` ({ name, url, icon }) the window is a site shortcut: no address bar,
    // just back / forward / reload / home, and the window keeps the app's name.
    function openBrowser(startUrl, app) {
      const el = document.createElement("div");
      el.className = app ? "app site-app" : "app";
      const svg = (d) => ``;
      const nav = `${svg("M15 18l-6-6 6-6")}${svg("M9 18l6-6-6-6")}${svg("M21 12a9 9 0 1 1-3-6.7L21 8M21 3v5h-5")}`;
      el.innerHTML = app
        ? `${nav}${svg("M3 11l9-8 9 8M5 10v10h14V10")}`
        : `${nav}Go`;
      const input = el.querySelector("input");
      const iframe = el.querySelector("iframe");
      const win = openWindow(app ? app.name : "Browser", el, { app: app ? app.name : "Browser" });
      if (app) el.querySelector(".app-title").textContent = app.name;
      let tab = null;

      const ready = proxyReady.then((engine) => (tab = engine.attach(iframe)), (e) => {
        iframe.srcdoc = `
Proxy failed to start: ${String(e.message).replace(/</g, "<")}
Try a different engine or transport in Settings.`;
        throw e;
      });

      async function go(raw) {
        const url = toUrl(raw);
        input.value = url;
        await ready;
        tab.go(url);
      }
      el.querySelector("form").addEventListener("submit", (e) => { e.preventDefault(); go(input.value); });
      if (!app) input.addEventListener("focus", fillHistoryList);

      // The proxied page is same-origin, so its history can be driven directly.
      el.querySelectorAll("[data-nav]").forEach((b) => (b.onclick = () => {
        try {
          const w = iframe.contentWindow;
          if (b.dataset.nav === "home") go(app.url);
          else if (b.dataset.nav === "back") w.history.back();
          else if (b.dataset.nav === "forward") w.history.forward();
          else w.location.reload();
        } catch {}
      }));

      // Keep the address bar and title in sync with in-page navigation.
      let retries = 0;
      iframe.addEventListener("load", () => {
        hookPanic(iframe);
        // App windows: a flaky upstream TLS connect (duck.ai does this) shows the SW's error
        // page; retry by itself up to 3 times, waiting 1 s, 2 s, then 4 s.
        try {
          if (app && retries < 3 && /^Internal Service Worker Error/.test(iframe.contentDocument.body?.innerText || "")) {
            const wait = 1000 * 2 ** retries++;
            return setTimeout(() => iframe.contentWindow.location.reload(), wait);
          }
        } catch {}
        // Block ads: proxied pages can't open pop-up / pop-under tabs.
        if (settings.adblock) try { iframe.contentWindow.open = () => null; } catch {}
        try {
          const real = tab?.current();
          if (real) {
            input.value = real;
            if (!app) win.setTitle(iframe.contentDocument.title || real);
            addHistory(real, iframe.contentDocument.title);
            runUserscripts(iframe, real);
          }
        } catch {}
      });

      if (startUrl) go(startUrl);
      else input.focus();
      return win;
    }

    // ======================= Games app =======================
    // /catalog/ merges Truffled, Seraph, Chicken King's Vault and UGS into
    // { source, name, cover, url, mirrors?, names?, launch } entries.
    let catalogPromise;
    const loadCatalog = () =>
      (catalogPromise ??= (STATIC ? staticCatalog() : fetch("/catalog/").then((r) => {
        if (!r.ok) throw new Error("catalog " + r.status);
        return r.json();
      })).catch((e) => { catalogPromise = null; throw e; }));

    // Static build: the same merge as catalog.js, done in the browser (GitHub and jsDelivr
    // allow cross-origin reads). Games that need the proxy ("proxy" launch) are left out.
    async function staticCatalog() {
      const getText = async (url) => { const r = await fetch(url); if (!r.ok) throw new Error(`${r.status} from ${url}`); return r.text(); };
      const latestSha = async (repo) => {
        try {
          const r = await fetch(`https://api.github.com/repos/${repo}/commits/main`, { headers: { accept: "application/vnd.github.sha" } });
          const sha = r.ok ? (await r.text()).trim() : "";
          if (/^[0-9a-f]{40}$/.test(sha)) return sha;
        } catch {}
        return "main";
      };
      const raw = (repo, ref, path) => `https://raw.githubusercontent.com/${repo}/${ref}/${path}`;
      const jsd = (repo, ref, path) => `https://cdn.jsdelivr.net/gh/${repo}@${ref}/${path}`;
      const decode = (s) => s.replace(/&/g, "&").replace(/</g, "<").replace(/>/g, ">").replace(/"/g, '"').replace(/'/g, "'").trim();
      const sources = {
        async truffled() {
          const repo = "skidding-code/truffled-lib", sha = await latestSha(repo);
          return JSON.parse(await getText(raw(repo, sha, "zones.json"))).flatMap((z) => {
            const url = String(z.url), base = { source: "Truffled", name: z.name, cover: z.cover, names: z.altNames };
            if (url.startsWith("http")) return []; // needs the proxy
            if (z.special?.includes("threads")) return [{ ...base, url: `https://cdn.jsdelivr.net/gh/${repo}@coi3/index.xhtml?g=${z.id}`, launch: "threads" }];
            const file = url.replace("{HTML_URL}/", "html/");
            return [{ ...base, url: jsd(repo, sha, file), mirrors: [jsd(repo, "lib", file), raw(repo, sha, file)], launch: "write" }];
          });
        },
        async seraph() {
          const repo = "a456pur/seraph", sha = await latestSha(repo);
          const site = `https://rawcdn.githack.com/${repo}/${sha}/games/`;
          const html = await getText(raw(repo, sha, "games/index.html"));
          const re = /]*href="([^"]+)"[^>]*>\s*
]*url\('([^']+)'\)[^>]*>\s*
([^<]+)<\/h2>/g;
          const seen = new Set(), out = [];
          for (const [, href, thumb, name] of html.matchAll(re)) {
            if (/^(https?:)?\/\//.test(href) || seen.has(href)) continue;
            seen.add(href);
            out.push({ source: "Seraph", name: decode(name), cover: new URL(thumb, site).href, url: new URL(href, site).href, launch: "frame" });
          }
          return out;
        },
        async chickenKingsVault() {
          const repo = "wanocapy/ChickenKingsVault", site = "https://wanocapy.github.io/ChickenKingsVault/";
          const js = await getText(raw(repo, await latestSha(repo), "games.js"));
          const re = /<a class="game-link" href="([^"]+)">\s*<img src="([^"]+)"[^>]*>\s*
([^<]+)<\/div>/g;
          return [...js.matchAll(re)].map(([, href, img, name]) => ({ source: "Chicken King's Vault", name: decode(name), cover: new URL(img, site).href, url: new URL(href, site).href, launch: "frame" }));
        },
        async ugs() {
          const repo = "bubbls/ugs-singlefile", sha = await latestSha(repo);
          const js = await getText(raw(repo, sha, "games.js"));
          const start = js.indexOf("["), list = js.slice(start, js.indexOf("];", start) + 1);
          const extra = new Set(["supremeduelistfix", "thiefpuzzle"]);
          return [...list.matchAll(/"((?:[^"\\]|\\.)*)"/g)].map((m) => m[1]).filter((n) => n.startsWith("cl") || extra.has(n)).map((n) => {
            const file = "UGS-Files/" + encodeURIComponent(n + ".html");
            return { source: "UGS", name: n.startsWith("cl") ? n.slice(2) : n, cover: null, url: jsd(repo, sha, file), mirrors: [raw(repo, sha, file)], launch: "write" };
          });
        },
      };
      const lists = await Promise.all(Object.entries(sources).map(([k, f]) => f().catch((e) => { console.warn(`catalog: ${k} failed: ${e.message}`); return []; })));
      const games = lists.flat();
      if (!games.length) throw new Error("couldn't load any game library");
      return games;
    }

    // Initial-letter tile for games without a cover (or whose cover fails to load).
    function letterIcon(name) {
      const d = document.createElement("div");
      d.className = "letter";
      const ch = (name.match(/[a-z0-9]/i) || ["?"])[0].toUpperCase();
      d.textContent = ch;
      let h = 0;
      for (const c of name) h = (h * 31 + c.charCodeAt(0)) >>> 0;
      d.style.background = `hsl(${h % 360} 55% 45%)`;
      return d;
    }

    // Favorites and recently played games ("source|name" keys; URLs change with each catalog
    // commit). Saved locally, and to the account when signed in. "write" games that have been
    // played once also work offline: sw.js keeps their files.
    const FAV_KEY = "proxyos-favorites", PLAYED_KEY = "proxyos-played";
    const gameKey = (g) => g.source + "|" + g.name;
    const readList = (k) => { try { const v = JSON.parse(localStorage.getItem(k) || "[]"); return Array.isArray(v) ? v : []; } catch { return []; } };
    let favorites = new Set(readList(FAV_KEY));
    let played = readList(PLAYED_KEY);
    // Notepad notes: [{id, text, updated}] (synced to the account like favorites).
    const NOTES_KEY = "proxyos-notes";
    let notes = readList(NOTES_KEY);
    let notesRender = null; // set while a Notepad window is open
    function notesChanged() { notesRender?.(); }
    function saveNotes() {
      try { localStorage.setItem(NOTES_KEY, JSON.stringify(notes)); } catch {}
      queueSync();
    }
    function saveGameLists() {
      try {
        localStorage.setItem(FAV_KEY, JSON.stringify([...favorites]));
        localStorage.setItem(PLAYED_KEY, JSON.stringify(played));
      } catch {}
      queueSync();
    }
    const worksOffline = (g) => g.launch === "write" && played.includes(gameKey(g));

    function openGames() {
      const el = document.createElement("div");
      el.className = "app";
      el.innerHTML = `


All games★ FavoritesPlayed (offline-ready)
Loading…







            ☆
            ⛶
            ⬇
            ✕

        `;
      const input = el.querySelector("input");
      const select = el.querySelector("select");
      const status = el.querySelector(".status");
      const grid = el.querySelector(".grid");
      const win = openWindow("Games", el);

      // ---- Player view: one game at a time inside this window ----
      const picker = el.querySelector(".picker");
      const player = el.querySelector(".player");
      const msg = el.querySelector(".game-msg");
      let current = null, frame = null, refresh = () => {};
      const favBtn = player.querySelector('[data-act="fav"]');
      const markFavBtn = () => {
        const on = !!current && favorites.has(gameKey(current));
        favBtn.classList.toggle("on", on);
        favBtn.innerHTML = on ? "★" : "☆";
        favBtn.title = on ? "Remove from favorites" : "Add to favorites";
      };
      const toggleFav = (g) => {
        const k = gameKey(g);
        favorites.has(k) ? favorites.delete(k) : favorites.add(k);
        saveGameLists();
        refresh();
        markFavBtn();
      };
      favBtn.onclick = () => current && toggleFav(current);
      const play = (g) => {
        played = [gameKey(g), ...played.filter((k) => k !== gameKey(g))].slice(0, 200);
        saveGameLists();
        if (g.launch === "proxy") return openBrowser(g.url); // external sites go through the proxy Browser
        current = g;
        markFavBtn();
        frame = document.createElement("iframe");
        frame.allow = "autoplay; fullscreen; gamepad; cross-origin-isolated";
        player.append(frame);
        el.querySelector(".game-title").textContent = g.name;
        msg.textContent = "";
        picker.hidden = true;
        player.hidden = false;
        win.setTitle(g.name);
        launchGame(g, frame);
      };
      const closeGame = () => {
        frame?.remove(); // removing the iframe stops the game and its sound
        frame = current = null;
        refresh();
        player.hidden = true;
        picker.hidden = false;
        win.setTitle("Games");
      };
      player.querySelector('[data-act="close"]').onclick = closeGame;
      player.querySelector('[data-act="fullscreen"]').onclick = () => frame?.requestFullscreen?.().catch(() => {});
      player.querySelector('[data-act="download"]').onclick = async () => {
        if (!current) return;
        msg.textContent = "Preparing download…";
        try {
          const { offline } = await downloadGame(current);
          msg.textContent = offline ? "Downloaded." : "Downloaded (needs internet to play).";
        } catch (e) {
          msg.textContent = "Download failed: " + e.message;
        }
      };

      loadCatalog().then((games) => {
        for (const s of [...new Set(games.map((g) => g.source))]) {
          select.append(new Option(`${s} (${games.filter((g) => g.source === s).length})`, s));
        }
        const frag = document.createDocumentFragment();
        const items = games.map((g) => {
          const wrap = document.createElement("div");
          wrap.className = "tile-wrap";
          const b = document.createElement("button");
          b.className = "game";
          b.title = `${g.name} — ${g.source}`;
          if (g.cover) {
            const img = document.createElement("img");
            img.loading = "lazy";
            img.alt = "";
            img.src = g.cover;
            img.onerror = () => img.replaceWith(letterIcon(g.name));
            b.append(img);
          } else {
            b.append(letterIcon(g.name));
          }
          const label = document.createElement("span");
          label.textContent = g.name;
          const src = document.createElement("small");
          src.textContent = g.source;
          const badge = Object.assign(document.createElement("small"), { className: "game-badge" });
          b.append(label, src, badge);
          b.onclick = () => play(g);
          const star = document.createElement("button");
          star.className = "fav";
          star.type = "button";
          star.onclick = (e) => { e.stopPropagation(); toggleFav(g); };
          wrap.append(b, star);
          frag.append(wrap);
          return { g, wrap, star, badge, hay: [g.name, ...(g.names || [])].join(" ").toLowerCase(), source: g.source };
        });
        grid.append(frag);
        const filter = (keepScroll) => {
          const q = input.value.trim().toLowerCase();
          const s = select.value;
          let n = 0;
          for (const it of items) {
            const k = gameKey(it.g), fav = favorites.has(k);
            const inList = !s || (s === "@fav" ? fav : s === "@played" ? played.includes(k) : it.source === s);
            const show = inList && (!q || it.hay.includes(q));
            it.wrap.hidden = !show;
            n += show;
            if (it.fav !== fav) { // only touch the DOM when something changed (≈5000 tiles)
              it.fav = fav;
              it.star.classList.toggle("on", fav);
              it.star.textContent = fav ? "★" : "☆";
              it.star.title = fav ? "Remove from favorites" : "Add to favorites";
            }
            const off = worksOffline(it.g);
            if (it.off !== off) { it.off = off; it.badge.textContent = off ? "✓ Works offline" : ""; }
          }
          status.textContent = s === "@fav" && !n && !q ? "No favorites yet. Hover a game and click its ☆." : `${n} games`;
          if (keepScroll !== true) grid.scrollTop = 0;
        };
        refresh = () => filter(true);
        input.addEventListener("input", filter);
        select.addEventListener("change", filter);
        filter();
        input.focus();
      }, (e) => (status.textContent = "Couldn't load catalog: " + e.message));
    }

    async function fetchFirst(urls) {
      let last;
      for (const u of urls) {
        try {
          const r = await fetch(u);
          if (r.ok) return { html: await r.text(), url: r.url || u };
          last = new Error(r.status + " " + r.statusText);
        } catch (e) { last = e; }
      }
      throw last;
    }

    // Load game `g` into `frame` (proxy games are handled by the caller).
    async function launchGame(g, frame) {
      // "frame": static game sites (Seraph via githack, Chicken King's Vault on GitHub Pages).
      // "threads": truffled games needing SharedArrayBuffer, served cross-origin-isolated by jsDelivr.
      if (g.launch === "frame" || g.launch === "threads") {
        frame.src = g.url;
        return;
      }

      // "write": CDN games – fetch the HTML and write it into a same-origin (about:blank) iframe. Not proxied.
      try {
        const { html } = await fetchFirst([g.url, ...(g.mirrors || [])]);
        const doc = frame.contentDocument;
        doc.open();
        doc.write(html);
        doc.close();
        hookPanic(frame);
      } catch (e) {
        frame.srcdoc = "Couldn't load game: " + String(e.message).replace(/</g, "<");
      }
    }

    // Save game `g` as a standalone .html that runs when opened from the file manager.
    // The game's own HTML is saved with a  pointing at where it came from, so any
    // separate files it loads (scripts, images, sounds) still come from the CDN.
    // Single-file games then work fully offline. If the HTML can't be fetched (CORS) or the
    // game needs cross-origin isolation ("threads"), a small launcher file is saved instead.
    async function downloadGame(g) {
      const esc = (s) => String(s).replace(/[&<>"]/g, (c) => `&#${c.charCodeAt(0)};`);
      let html = null, offline = false;
      if (g.launch === "write" || g.launch === "frame") {
        try {
          const got = await fetchFirst(g.launch === "write" ? [g.url, ...(g.mirrors || [])] : [g.url]);
          html = got.html;
          const own = html.match(/]*href\s*=\s*["']?([^"'\s>]+)/i);
          const base = own ? new URL(own[1], got.url).href : got.url;
          html = html.replace(/]*>/gi, "");
          const tag = ``;
          const dt = html.match(/^\s*]*>/i); // keep the doctype first (else quirks mode)
          html = dt ? dt[0] + tag + html.slice(dt[0].length) : tag + html;
          // Offline if it doesn't pull in any external files (scripts, styles, images, media, frames).
          offline = !/<(script|link|img|iframe|source|audio|video|embed|object)\b[^>]*\b(src|href|data)\s*=\s*["']?(?!data:|blob:|#)[^"'\s>]/i.test(html);
        } catch { html = null; }
      }
      if (html == null) {
        html = g.launch === "threads"
          // Needs cross-origin isolation, which a local file can't provide, so jump to the real page.
          ? `${esc(g.name)}location.replace(${JSON.stringify(g.url)})<\/script>Play ${esc(g.name)}`
          : `${esc(g.name)}`;
      }
      const a = document.createElement("a");
      a.href = URL.createObjectURL(new Blob([html], { type: "text/html" }));
      a.download = (g.name.replace(/[\\/:*?"<>|]+/g, "").trim() || "game") + ".html";
      document.body.append(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 10000);
      return { offline };
    }

    // ======================= Cloaking =======================
    const CLOAKS = [
      { id: "classroom", name: "Google Classroom", title: "Home", domain: "classroom.google.com" },
      { id: "gmail", name: "Gmail", title: "Inbox - Gmail", domain: "mail.google.com" },
      { id: "drive", name: "Google Drive", title: "My Drive - Google Drive", domain: "drive.google.com" },
      { id: "docs", name: "Google Docs", title: "Untitled document - Google Docs", domain: "docs.google.com" },
      { id: "google", name: "Google", title: "Google", domain: "google.com" },
      { id: "schoology", name: "Schoology", title: "Home | Schoology", domain: "schoology.com" },
      { id: "deltamath", name: "DeltaMath", title: "DeltaMath", domain: "deltamath.com" },
      { id: "canvas", name: "Canvas", title: "Dashboard", domain: "instructure.com" },
      { id: "clever", name: "Clever", title: "Clever | Portal", domain: "clever.com" },
      { id: "khan", name: "Khan Academy", title: "Khan Academy", domain: "khanacademy.org", url: "https://www.khanacademy.org/" },
      { id: "ixl", name: "IXL", title: "IXL | Dashboard", domain: "ixl.com" },
      { id: "quizlet", name: "Quizlet", title: "Quizlet", domain: "quizlet.com" },
      { id: "desmos", name: "Desmos", title: "Desmos | Graphing Calculator", domain: "desmos.com" },
      { id: "edpuzzle", name: "Edpuzzle", title: "Edpuzzle", domain: "edpuzzle.com" },
      { id: "kahoot", name: "Kahoot!", title: "Kahoot!", domain: "kahoot.it" },
    ];
    const iconFor = (domain) => `https://www.google.com/s2/favicons?domain=${domain}&sz=64`;
    // GhettoOS logo (lock screen, menu bar, About, tab favicon when not disguised): the user's
    // armillary-sphere engraving, cropped to the sphere's outer ring so it fills a circle exactly
    // (centre 208,186, radius 183 in armillary.png → 512×512 armillary-logo.png).
    const GHETTO_ICON = "data:image/png;base64,";
    const ORIGINAL = { title: "GhettoOS", icon: GHETTO_ICON };
    function useLogo(src) {
      ORIGINAL.icon = src;
      document.querySelectorAll(".logo-img").forEach((i) => (i.src = src));
    }

    // Tab title / icon: the disguise preset, with Settings' title and icon overrides on top.
    function currentCloak() {
      const c = CLOAKS.find((c) => c.id === settings.cloak);
      return {
        title: settings.cloakTitle || c?.title || ORIGINAL.title,
        icon: settings.cloakIcon || (c ? iconFor(c.domain) : ORIGINAL.icon),
      };
    }
    function applyCloak() {
      if (covered) return; // the unfocused cover owns the title while it's up
      const { title, icon } = currentCloak();
      document.title = title;
      document.getElementById("favicon").href = icon;
    }

    // Open this site inside an about:blank tab (the address bar then shows about:blank).
    function openAboutBlank(silent) {
      const w = window.open("about:blank", "_blank");
      if (!w) { if (!silent) alert("Pop-up blocked. Allow pop-ups for this site and try again."); return; }
      const { title, icon } = currentCloak();
      const d = w.document;
      d.title = title;
      const link = d.createElement("link");
      link.rel = "icon";
      link.href = icon;
      d.head.append(link);
      d.body.style.margin = "0";
      const f = d.createElement("iframe");
      f.src = location.href;
      f.style.cssText = "border:0;position:fixed;inset:0;width:100%;height:100%";
      d.body.append(f);
    }

    // ======================= Cover when unfocused =======================
    // While the tab is hidden or focus is elsewhere (another window, the address bar), a decoy
    // site covers everything and the tab title/icon match it. document.hasFocus() stays true
    // while an iframe inside GhettoOS has focus, so clicking into a window doesn't trigger it.
    const coverEl = document.getElementById("cover");
    let covered = false, coverLoadedFor = null;
    const coverSite = () => CLOAKS.find((c) => c.id === settings.blurSite) || CLOAKS.find((c) => c.id === "khan");
    function showCover() {
      const c = coverSite();
      document.title = c.title;
      document.getElementById("favicon").href = iconFor(c.domain);
      if (coverLoadedFor !== c.id) { // load the decoy once, then keep it
        coverLoadedFor = c.id;
        coverEl.innerHTML = "";
        const f = coverEl.firstChild;
        proxyReady.then((engine) => engine.attach(f).go(c.url || "https://" + c.domain + "/")).catch(() => {});
      }
      coverEl.hidden = false;
    }
    function hideCover() {
      coverEl.hidden = true;
      applyCloak();
    }
    setInterval(() => {
      const away = settings.blurCloak && (document.hidden || !document.hasFocus());
      if (away === covered) return;
      covered = away;
      away ? showCover() : hideCover();
    }, 250);

    // ======================= Tab redirect (panic) key =======================
    // Jumps this tab to the redirect URL, and (optionally) first reopens GhettoOS in an
    // about:blank tab. Also hooked into same-origin iframes (proxied pages, CDN games).
    const isTyping = (t) => !!t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName || ""));
    const withScheme = (u) => (/^[a-z][a-z0-9+.-]*:/i.test(u) ? u : "https://" + u);
    function onPanicKey(e) {
      if (!settings.panicKey || e.key !== settings.panicKey || e.repeat || isTyping(e.target)) return;
      e.preventDefault();
      if (settings.panicBlank) openAboutBlank(true);
      window.top.location.href = withScheme(settings.panicUrl || DEFAULTS.panicUrl);
    }
    function hookPanic(iframe) {
      try { iframe.contentWindow.addEventListener("keydown", onPanicKey, true); } catch {}
    }
    window.addEventListener("keydown", onPanicKey, true);

    // ======================= Ad blocking =======================
    // sw.js reads the setting from Cache Storage (it can't see localStorage) and gets live updates.
    async function syncAdblock() {
      try {
        const c = await caches.open("proxyos-config");
        await c.put("/__config/adblock", new Response(settings.adblock ? "1" : "0"));
        const reg = await navigator.serviceWorker.getRegistration("/");
        reg?.active?.postMessage({ adblock: settings.adblock });
      } catch {}
    }

    // ======================= Appearance =======================
    // Wallpapers are pure CSS (no images), so they cost nothing to keep on screen.
    const glow = (a, b) => `radial-gradient(ellipse 70% 55% at 20% 20%, ${a}, transparent 70%), radial-gradient(ellipse 60% 50% at 85% 85%, ${b}, transparent 70%)`;
    const THEMES = {
      nebula: { name: "Nebula", bg: "var(--wall)" },
      midnight: { name: "Midnight", bg: "#08080d" },
      graphite: { name: "Graphite", bg: "#1b1b22" },
      ocean: { name: "Deep ocean", bg: `${glow("rgba(30, 90, 170, .45)", "rgba(20, 130, 140, .3)")}, #050a16` },
      plum: { name: "Plum", bg: `${glow("rgba(140, 50, 160, .45)", "rgba(220, 80, 120, .25)")}, #0d0614` },
      forest: { name: "Forest", bg: `${glow("rgba(30, 120, 80, .40)", "rgba(180, 150, 60, .22)")}, #050d0a` },
      ember: { name: "Ember", bg: `${glow("rgba(190, 80, 40, .40)", "rgba(224, 184, 102, .25)")}, #120806` },
      gold: { name: "Antique gold", bg: `${glow("rgba(224, 184, 102, .35)", "rgba(120, 80, 30, .3)")}, #0e0b06` },
    };
    const ANIM_BGS = { none: "None", aurora: "Aurora", stars: "Starfield", lava: "Lava lamp" };
    function applyAppearance() {
      const t = THEMES[settings.theme] || THEMES.nebula;
      const anim = ANIM_BGS[settings.animBg] && settings.animBg !== "none" ? settings.animBg : "";
      document.body.style.background = t.bg;
      document.getElementById("bg").className = anim ? "bg-" + anim : "dust";
      document.body.classList.toggle("compact", settings.layout === "compact");
    }

    // ======================= Visited sites =======================
    const HISTORY_KEY = "proxyos-history";
    let visited = [];
    try { visited = JSON.parse(localStorage.getItem(HISTORY_KEY) || "[]"); } catch {}
    function addHistory(url, title) {
      if (!/^https?:\/\//.test(url)) return;
      visited = [{ url, title: title || "" }, ...visited.filter((h) => h.url !== url)].slice(0, 200);
      try { localStorage.setItem(HISTORY_KEY, JSON.stringify(visited)); } catch {}
    }
    function clearHistory() {
      visited = [];
      try { localStorage.removeItem(HISTORY_KEY); } catch {}
      fillHistoryList();
    }
    function fillHistoryList() { //  behind every Browser address bar
      const list = document.getElementById("history-list");
      list.replaceChildren(...visited.map((h) => Object.assign(document.createElement("option"), { value: h.url, label: h.title })));
    }

    // ======================= Userscripts =======================
    // Greasemonkey-style scripts ({ name, matches, code }) injected into matching proxied pages
    // when they finish loading, with a small GM_* shim. Added by URL (downloaded once through
    // /api/userscript) or by pasting the code.
    const USERSCRIPTS_KEY = "proxyos-userscripts";
    let userscripts = [];
    try { userscripts = JSON.parse(localStorage.getItem(USERSCRIPTS_KEY) || "[]"); } catch {}
    function saveUserscripts() {
      queueSync();
      try { localStorage.setItem(USERSCRIPTS_KEY, JSON.stringify(userscripts)); return true; } catch { return false; }
    }
    function parseUserscriptMeta(code) {
      const meta = code.match(/==UserScript==([\s\S]*?)==\/UserScript==/)?.[1] || "";
      return {
        name: meta.match(/@name\s+(.+)/)?.[1].trim(),
        matches: [...meta.matchAll(/@(?:match|include)\s+(\S+)/g)].map((m) => m[1]),
      };
    }
    function patternToRegExp(p) {
      if (p === "*" || p === "") return /^https?:\/\//;
      if (p.length > 2 && p.startsWith("/") && p.endsWith("/")) { try { return new RegExp(p.slice(1, -1)); } catch { return null; } }
      // Greasemonkey glob: "*://*.site.com/*" also matches site.com itself.
      const parts = p.replace("://*.", "://\u0001").split("*").map((s) => s.replace(/[.+?^${}()|[\]\\]/g, "\\$&"));
      return new RegExp("^" + parts.join(".*").replace("\u0001", "(?:[^/]*\\.)?") + "$");
    }
    const userscriptMatches = (s, url) => (s.matches.length ? s.matches : ["*"]).some((m) => patternToRegExp(m)?.test(url));
    const GM_SHIM = `const unsafeWindow = window, GM_info = { script: {} };
const GM_addStyle = (css) => { const s = document.createElement("style"); s.textContent = css; (document.head || document.documentElement).append(s); return s; };
const GM_getValue = (k, d) => { try { const v = localStorage.getItem("GM_" + k); return v == null ? d : JSON.parse(v); } catch { return d; } };
const GM_setValue = (k, v) => { try { localStorage.setItem("GM_" + k, JSON.stringify(v)); } catch {} };
const GM_deleteValue = (k) => { try { localStorage.removeItem("GM_" + k); } catch {} };
const GM_openInTab = (u) => window.open(u, "_blank");
`;
    function runUserscripts(iframe, url) {
      for (const s of userscripts) {
        if (!s.enabled || !userscriptMatches(s, url)) continue;
        try {
          const d = iframe.contentDocument;
          const el = d.createElement("script");
          el.textContent = `(function () {\n${GM_SHIM}${s.code}\n})();`;
          (d.head || d.documentElement).append(el);
        } catch (e) { console.warn("userscript failed:", s.name, e); }
      }
    }
    async function addUserscript(input) {
      let code = input.trim();
      if (!code) throw new Error("Paste a script URL or its code first.");
      let source = "";
      if (/^https?:\/\/\S+$/.test(code)) {
        source = code;
        const r = await fetch("/api/userscript?url=" + encodeURIComponent(code));
        code = await r.text();
        if (!r.ok) throw new Error(code);
      }
      const { name, matches } = parseUserscriptMeta(code);
      const script = { id: Date.now().toString(36), name: name || "Untitled script", matches, code, source, enabled: true };
      userscripts.push(script);
      if (!saveUserscripts()) { userscripts.pop(); throw new Error("Not enough storage space for that script."); }
      return script;
    }

    // ======================= Clear all data =======================
    async function clearAllData() {
      if (!confirm(STATIC
        ? "Clear all GhettoOS data on this device? This removes your settings, scripts, notes and every account saved in this browser."
        : "Clear all GhettoOS data on this device? This removes your settings, scripts, visited sites, and the cookies and logins of every site you've opened here, and signs you out. Your account's saved settings stay on the server.")) return;
      try { await fetch("/api/auth/logout", { method: "POST" }); } catch {}
      try { localStorage.clear(); sessionStorage.clear(); } catch {}
      try { // proxied sites' cookies and storage live in IndexedDB
        const dbs = await indexedDB.databases();
        await Promise.all(dbs.map((d) => new Promise((done) => {
          const q = indexedDB.deleteDatabase(d.name);
          q.onsuccess = q.onerror = q.onblocked = () => done();
        })));
      } catch {}
      try { for (const k of await caches.keys()) await caches.delete(k); } catch {}
      try { for (const r of await navigator.serviceWorker.getRegistrations()) await r.unregister(); } catch {}
      for (const c of document.cookie.split(";")) {
        const name = c.split("=")[0].trim();
        if (name) document.cookie = name + "=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/";
      }
      location.reload();
    }

    // ======================= Settings app =======================
    function openSettings() {
      const el = document.createElement("div");
      el.className = "app settings";
      const toggle = (n) => ``;
      const row = (title, desc, ctl) => `

${title}${desc}${ctl ? `
${ctl}` : ""}`;
      el.innerHTML = `



Account
          ${row(``, ``, ``)}



Privacy
          ${row("Cover when unfocused", "Covers GhettoOS with another site whenever you click away or switch tabs, until you come back.", toggle("blurCloak"))}
          ${row("Cover page", "The site shown while covered. The tab title and icon change to match it.", ``)}
          ${row("Open in about:blank", "Reopens GhettoOS inside an about:blank tab, so the address bar only shows about:blank.", `Open`)}



Tab
          ${row("Disguise", "Makes this browser tab look like another site.", "")}


          ${row("Tab title", "Shown on the browser tab. Leave empty to use the disguise's title.", ``)}
          ${row("Favicon", "Icon shown on the browser tab. Paste an image URL, or leave empty to use the disguise's icon.", ``)}



Tab redirect
          ${row("Key", "Press it anywhere in GhettoOS to leave instantly. Ignored while typing in a text box.", `Off`)}
          ${row("Redirect URL", "Where this tab goes when the key is pressed.", ``)}
          ${row("Reopen in about:blank", "Also reopens GhettoOS in a new about:blank tab, so you can get back to it.", toggle("panicBlank"))}



Browsing
          ${row("Block ads", "Stops ads, pop-up tabs and trackers on sites you open through GhettoOS. Turn it off if a site breaks or won't load.", toggle("adblock"))}
          ${row("Search engine", "Used when you type something that isn't an address.", ``)}
          ${row("Custom search URL", "Only used with “Custom…”. Put %s where the search words go.", ``)}



Appearance
          ${row("Wallpaper", "Desktop background. All are drawn with CSS, so they use no extra memory.", `
`)}
          ${row("Animated background", "Moving scenes that replace the wallpaper.", `
`)}
          ${row("Dock size", "Compact makes the dock icons smaller.", `ClassicCompact`)}
          ${row("Lock screen on start", "Shows the GhettoOS lock screen whenever the page opens.", toggle("lockOnStart"))}



Userscripts
          ${row("Your scripts", "Run on matching sites you open through GhettoOS (Greasy Fork style, using the script's @match lines). Only add scripts you trust.", "")}



Add





Proxy
          ${row("Engine", "Scramjet v2 works best. Only switch if sites won't load.", ``)}
          ${row("Transport", "How proxied traffic reaches the internet.", ``)}
          ${row("Wisp server", "Leave empty to use this server.", ``)}
          ${row("Apply proxy changes", "Engine, transport and Wisp changes reload GhettoOS.", `Apply & reload`)}



Data
          ${row("Visited sites", "Sites you've opened, suggested in the Browser's address bar. They stay on this device.", `Clear visited sites`)}
          ${row("Site data", "Removes your settings, scripts, visited sites, and the cookies and logins of sites you've opened through GhettoOS.", `Clear all data`)}

      `;
      const $ = (n) => el.querySelector(`[name="${n}"]`);
      const set = (k, v) => { settings[k] = v; saveSettings(); };
      const fill = (sel, opts, value) => {
        for (const [k, v] of Object.entries(opts)) sel.append(new Option(typeof v === "string" ? v : v.name, k));
        sel.value = value;
      };
      const pressed = (buttons, isOn) => buttons.forEach(([id, b]) => b.setAttribute("aria-pressed", isOn(id)));

      // Account
      const renderAcct = () => {
        if (!el.isConnected && onAccountChange.has(renderAcct)) return onAccountChange.delete(renderAcct); // window closed
        el.querySelector("[data-acct-title]").textContent = account ? `Signed in as ${account}` : "Guest";
        el.querySelector("[data-acct-desc]").textContent = account
          ? "Your wallpaper, settings, scripts and favorite games are saved to your account and follow you to any device."
          : "Settings only stay on this device. Sign in or create an account to save them and to use Chat.";
        $("acctBtn").textContent = account ? "Sign out" : "Sign in";
        $("acctBtn").className = account ? "btn danger" : "btn primary";
      };
      renderAcct();
      onAccountChange.add(renderAcct);
      $("acctBtn").onclick = () => (account ? signOut() : lockScreen());

      // Toggles
      for (const n of ["blurCloak", "panicBlank", "adblock", "lockOnStart"]) $(n).checked = !!settings[n];
      $("lockOnStart").onchange = () => set("lockOnStart", $("lockOnStart").checked);
      $("blurCloak").onchange = () => set("blurCloak", $("blurCloak").checked);
      $("panicBlank").onchange = () => set("panicBlank", $("panicBlank").checked);
      $("adblock").onchange = () => { set("adblock", $("adblock").checked); syncAdblock(); };

      // Privacy
      for (const c of CLOAKS) $("blurSite").append(new Option(c.name, c.id));
      $("blurSite").value = coverSite().id;
      $("blurSite").onchange = () => { set("blurSite", $("blurSite").value); };
      $("aboutBlank").onclick = () => openAboutBlank();

      // Tab disguise
      const titleHint = () => ($("cloakTitle").placeholder = CLOAKS.find((c) => c.id === settings.cloak)?.title || ORIGINAL.title);
      const cloakButtons = [{ id: "none", name: "Off (GhettoOS)", icon: GHETTO_ICON }, ...CLOAKS].map((c) => {
        const b = document.createElement("button");
        const img = document.createElement("img");
        img.src = c.icon || iconFor(c.domain);
        img.alt = "";
        b.append(img, c.name);
        b.onclick = () => { set("cloak", c.id); applyCloak(); titleHint(); pressed(cloakButtons, (id) => id === settings.cloak); };
        el.querySelector("[data-cloaks]").append(b);
        return [c.id, b];
      });
      pressed(cloakButtons, (id) => id === settings.cloak);
      titleHint();
      $("cloakTitle").value = settings.cloakTitle;
      $("cloakIcon").value = settings.cloakIcon;
      $("cloakTitle").oninput = () => { set("cloakTitle", $("cloakTitle").value); applyCloak(); };
      $("cloakIcon").onchange = () => { set("cloakIcon", $("cloakIcon").value.trim()); applyCloak(); };

      // Tab redirect
      $("panicKey").value = settings.panicKey;
      $("panicUrl").value = settings.panicUrl;
      $("panicKey").addEventListener("keydown", (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.key === "Tab" || e.key === "Escape") return;
        set("panicKey", e.key);
        $("panicKey").value = e.key === " " ? "Space" : e.key;
      });
      $("clearPanic").onclick = () => { set("panicKey", ""); $("panicKey").value = ""; };
      $("panicUrl").onchange = () => set("panicUrl", $("panicUrl").value.trim());

      // Browsing
      fill($("search"), SEARCH_ENGINES, settings.search);
      $("searchCustom").value = settings.searchCustom;
      $("search").onchange = () => set("search", $("search").value);
      $("searchCustom").onchange = () => set("searchCustom", $("searchCustom").value.trim());

      // Appearance
      const themeButtons = Object.entries(THEMES).map(([id, t]) => {
        const b = document.createElement("button");
        b.style.background = t.bg;
        b.title = b.ariaLabel = t.name;
        b.onclick = () => { set("theme", id); set("animBg", "none"); applyAppearance(); markLook(); };
        el.querySelector("[data-themes]").append(b);
        return [id, b];
      });
      const animButtons = Object.entries(ANIM_BGS).map(([id, name]) => {
        const b = document.createElement("button");
        b.textContent = name;
        b.onclick = () => { set("animBg", id); applyAppearance(); markLook(); };
        el.querySelector("[data-anims]").append(b);
        return [id, b];
      });
      const markLook = () => {
        pressed(themeButtons, (id) => settings.animBg === "none" && id === settings.theme);
        pressed(animButtons, (id) => id === settings.animBg);
      };
      markLook();
      $("layout").value = settings.layout;
      $("layout").onchange = () => { set("layout", $("layout").value); applyAppearance(); };

      // Userscripts
      const list = el.querySelector("[data-scripts]");
      const msg = el.querySelector("[data-usmsg]");
      const say = (text, isErr) => { msg.textContent = text; msg.classList.toggle("err", !!isErr); };
      const renderScripts = () => {
        list.replaceChildren(...userscripts.map((s) => {
          const r = document.createElement("div");
          r.className = "script";
          r.innerHTML = `
${toggle("enabled")}Remove`;
          r.querySelector("b").textContent = s.name;
          r.querySelector("small").textContent = s.matches.length ? "Runs on " + s.matches.join(", ") : "Runs on every site";
          const t = r.querySelector("input");
          t.checked = s.enabled;
          t.onchange = () => { s.enabled = t.checked; saveUserscripts(); };
          r.querySelector("[data-remove]").onclick = () => {
            userscripts = userscripts.filter((x) => x !== s);
            saveUserscripts();
            renderScripts();
            say(`Removed “${s.name}”.`);
          };
          return r;
        }));
      };
      renderScripts();
      $("usAdd").onclick = async () => {
        $("usAdd").disabled = true;
        say("Adding…");
        try {
          const s = await addUserscript($("usInput").value);
          $("usInput").value = "";
          renderScripts();
          say(`Added “${s.name}”. It runs the next time a matching site loads.`);
        } catch (e) { say(e.message, true); }
        $("usAdd").disabled = false;
      };

      // Proxy
      fill($("engine"), ENGINES, settings.engine);
      fill($("transport"), TRANSPORTS, settings.transport);
      $("wisp").value = settings.wisp;
      $("apply").onclick = () => {
        settings.engine = $("engine").value;
        settings.transport = $("transport").value;
        settings.wisp = $("wisp").value.trim();
        saveSettings();
        location.reload();
      };

      // Data
      $("clearHistory").onclick = () => { clearHistory(); $("clearHistory").textContent = "Cleared"; setTimeout(() => ($("clearHistory").textContent = "Clear visited sites"), 1500); };
      $("clearAll").onclick = clearAllData;

      openWindow("Settings", el, { width: Math.min(760, Math.round(innerWidth * 0.92)), height: Math.round((innerHeight - MENU_H - dockSpace()) * 0.94) });
    }

    // ======================= AI Chat =======================
    // Duck.ai (free, no login) loaded through the proxy: its own headers forbid being framed
    // directly (X-Frame-Options SAMEORIGIN, frame-ancestors duckduckgo.com).
    // Its dock icon is the armillary-sphere engraving (publicdata:image/png;base64,).
    const SPHERE = "data:image/png;base64,";

    // ======================= Dock =======================
    const GLYPHS = {
      browser: ``,
      games: ``,
      settings: ``,
      chat: ``,
      movies: ``,
      inbox: ``,
      trophy: ``,
      notepad: ``,
      calculator: ``,
      changelog: ``,
      idea: ``,
    };
    // Proxied sites open in app mode (no address bar).
    const SHORTCUTS = [
      { name: "AI Chat", url: "https://duck.ai/", domain: "duck.ai", sphere: true },
      { name: "YouTube", url: "https://www.youtube.com", domain: "youtube.com" },
      { name: "Spotify", url: "https://open.spotify.com", domain: "spotify.com" },
      { name: "TikTok", url: "https://www.tiktok.com", domain: "tiktok.com" },
      { name: "Instagram", url: "https://www.instagram.com", domain: "instagram.com" },
      { name: "Twitch", url: "https://www.twitch.tv", domain: "twitch.tv" },
      { name: "Discord", url: "https://discord.com/app", domain: "discord.com" },
    ];
    let DOCK_APPS = [
      { name: "Browser", glyph: "browser", open: () => openBrowser() },
      { name: "Games", glyph: "games", open: () => openGames() },
      { name: "Settings", glyph: "settings", open: () => openSettings() },
      { name: "Chat", glyph: "chat", open: () => openChat() },
      null, // separator
      ...SHORTCUTS.map((s) => ({ name: s.name, sphere: s.sphere, domain: s.domain,
        open: () => (STATIC && s.sphere ? openAIChat() : openBrowser(s.url, { ...s, icon: s.sphere ? SPHERE : iconFor(s.domain) })) })),
    ];
    // Apps that need server.js (the proxy, or shared accounts) aren't shown in the static build.
    const NEEDS_SERVER = new Set(["Browser", "Chat", "Movies", "Inbox", "Leaderboard", "Suggestions", ...SHORTCUTS.filter((s) => !s.sphere).map((s) => s.name)]);
    const available = (a) => !a || !STATIC || !NEEDS_SERVER.has(a.name);
    DOCK_APPS = DOCK_APPS.filter(available);
    // Desktop only (not in the dock).
    const MOVIES = { name: "Movies", url: "https://www.cineby.cx", domain: "cineby.cx" };
    const DESKTOP_APPS = [
      { name: "Movies", glyph: "movies", open: () => openBrowser(MOVIES.url, { ...MOVIES, icon: iconFor(MOVIES.domain) }) },
      { name: "Inbox", glyph: "inbox", open: () => openInbox() },
      { name: "Leaderboard", glyph: "trophy", open: () => openLeaderboard() },
      { name: "Notepad", glyph: "notepad", open: () => openNotepad() },
      { name: "Calculator", glyph: "calculator", open: () => openCalculator() },
      { name: "Changelog", glyph: "changelog", open: () => openChangelog() },
      { name: "Suggestions", glyph: "idea", open: () => openSuggestions() },
    ];
    const deskEls = {}; // app name -> desktop icon button
    const dock = document.getElementById("dock");
    const desktop = document.getElementById("desktop");
    const dockItems = [];
    function appTile(a) {
      const tile = document.createElement("span");
      if (a.glyph) {
        tile.className = "tile native";
        tile.innerHTML = `${GLYPHS[a.glyph]}`;
      } else {
        tile.className = a.sphere ? "tile sphere" : "tile site";
        const img = document.createElement("img");
        img.alt = "";
        img.src = a.sphere ? SPHERE : iconFor(a.domain);
        img.onerror = () => img.replaceWith(letterIcon(a.name));
        tile.append(img);
      }
      return tile;
    }
    // Bring back / focus the app's newest window, or open one if it has none.
    function launchApp(a) {
      const mine = [...openWindows].filter((r) => r.app === a.name);
      const r = mine[mine.length - 1];
      if (!r) return a.open();
      if (r.win.min) r.win.restore();
      r.win.focus();
    }
    if (STATIC) document.querySelectorAll('#mb-menu [data-act="browser"], #mb-menu [data-act="chat"]').forEach((b) => b.remove());
    for (const a of [...DOCK_APPS, ...DESKTOP_APPS.filter(available)]) {
      if (!a) { dock.append(Object.assign(document.createElement("div"), { className: "dock-sep" })); continue; }
      if (DOCK_APPS.includes(a)) {
        const b = document.createElement("button");
        b.className = "dock-item";
        b.setAttribute("aria-label", a.name);
        const tip = Object.assign(document.createElement("span"), { className: "tip", textContent: a.name });
        b.append(appTile(a), tip);
        b.onclick = () => launchApp(a);
        dock.append(b);
        dockItems.push({ app: a.name, el: b });
      }
      // Every app is also a desktop icon (dock apps stay in the dock too).
      const d = document.createElement("button");
      d.className = "desk-item";
      d.title = a.name;
      d.append(appTile(a), Object.assign(document.createElement("span"), { className: "label", textContent: a.name }));
      d.onclick = () => launchApp(a);
      desktop.append(d);
      deskEls[a.name] = d;
    }
    function setDeskBadge(app, n) {
      const d = deskEls[app];
      let b = d?.querySelector(".badge");
      if (!d) return;
      if (!n) return b?.remove();
      if (!b) d.append((b = Object.assign(document.createElement("span"), { className: "badge" })));
      b.textContent = n > 99 ? "99+" : n;
    }
    function refreshDock() {
      for (const it of dockItems) it.el.classList.toggle("running", [...openWindows].some((r) => r.app === it.app));
    }
    // Hover magnification: widths follow the pointer (positions measured at rest, so no feedback).
    let restCenters = null, magFrame = 0, lastX = 0;
    const iconSize = () => (settings.layout === "compact" || innerWidth <= 720 ? (innerWidth <= 720 ? 38 : 40) : 52);
    function magnify() {
      magFrame = 0;
      const base = iconSize();
      dockItems.forEach((it, i) => {
        const d = Math.abs(lastX - restCenters[i]);
        const s = 1 + 0.55 * Math.max(0, 1 - d / (base * 2.6)) ** 1.6;
        it.el.style.width = it.el.style.height = (base * s).toFixed(1) + "px";
      });
    }
    dock.addEventListener("mouseenter", () => {
      restCenters = dockItems.map((it) => { const r = it.el.getBoundingClientRect(); return r.left + r.width / 2; });
      dock.classList.add("magnify");
    });
    dock.addEventListener("mousemove", (e) => {
      if (!restCenters) return;
      lastX = e.clientX;
      if (!magFrame) magFrame = requestAnimationFrame(magnify);
    });
    dock.addEventListener("mouseleave", () => {
      cancelAnimationFrame(magFrame);
      magFrame = 0;
      restCenters = null;
      dock.classList.remove("magnify");
      dockItems.forEach((it) => (it.el.style.width = it.el.style.height = ""));
    });

    // ======================= Menu bar =======================
    const mbMenu = document.getElementById("mb-menu");
    const mbLogo = document.getElementById("mb-logo");
    const toggleMenu = (open = mbMenu.hidden) => { mbMenu.hidden = !open; mbLogo.setAttribute("aria-expanded", open); };
    mbLogo.onclick = (e) => { e.stopPropagation(); toggleMenu(); };
    document.addEventListener("pointerdown", (e) => { if (!mbMenu.hidden && !mbMenu.contains(e.target) && !mbLogo.contains(e.target)) toggleMenu(false); });
    mbMenu.onclick = (e) => {
      const act = e.target.closest("button")?.dataset.act;
      if (!act) return;
      toggleMenu(false);
      ({ about: openAbout, browser: () => openBrowser(), games: () => openGames(), settings: () => openSettings(), chat: () => openChat(),
         blank: () => openAboutBlank(), account: () => (account ? signOut() : lockScreen()), lock: lockScreen })[act]();
    };
    document.getElementById("mb-lock").onclick = () => lockScreen();
    function showUser() {
      document.getElementById("mb-user").textContent = account || "Guest";
      document.getElementById("mb-account").textContent = account ? `Sign out ${account}` : "Sign in…";
    }

    function openAbout() {
      const el = document.createElement("div");
      el.className = "app about";
      el.innerHTML = `
GhettoOS
Web desktop · Scramjet proxy · v${CHANGELOG[0].version}`;
      el.querySelector(".logo-img").src = ORIGINAL.icon;
      openWindow("About GhettoOS", el, { app: "About", width: 300, height: 340, x: "center", y: "center" });
    }

    // ======================= Lock screen =======================
    // Background video: public/assets/lockscreen-bg.mp4, played as a boomerang between 0:03
    // and 0:13. Forward is normal playback; backward steps currentTime once per frame, but
    // only after the previous seek finished, so slow devices just get fewer frames.
    const lockEl = document.getElementById("lock");
    const lockVideo = document.getElementById("lock-video");
    // The static build embeds the video only if it exists (window.GHETTO_LOCK_VIDEO).
    const LOCK_VIDEO = STATIC ? window.GHETTO_LOCK_VIDEO || "" : "/assets/lockscreen-bg.mp4";
    let loopA = 3, loopB = 13, reverse = false, boomFrame = 0, lastTs = 0;
    function boomerang(ts) {
      boomFrame = requestAnimationFrame(boomerang);
      const v = lockVideo, dt = lastTs ? Math.min(0.1, (ts - lastTs) / 1000) : 0;
      lastTs = ts;
      if (!reverse) {
        if (v.currentTime >= loopB) { v.pause(); reverse = true; }
      } else if (!v.seeking) {
        const t = v.currentTime - dt * 1.0;
        if (t <= loopA) { v.currentTime = loopA; reverse = false; v.play().catch(() => {}); }
        else v.currentTime = t;
      }
    }
    function startLockVideo() {
      if (lockVideo.dataset.failed) return;
      if (!LOCK_VIDEO) { lockVideo.hidden = true; return; }
      if (!lockVideo.src) {
        lockVideo.addEventListener("error", () => { lockVideo.dataset.failed = "1"; lockVideo.hidden = true; stopLockVideo(); }, { once: true });
        lockVideo.addEventListener("loadedmetadata", () => {
          const d = lockVideo.duration || 0;
          loopB = Math.min(13, Math.max(0.5, d - 0.05));
          loopA = Math.min(3, Math.max(0, loopB - 1));
          lockVideo.currentTime = loopA;
        }, { once: true });
        lockVideo.src = LOCK_VIDEO;
      }
      reverse = false;
      lastTs = 0;
      lockVideo.play().catch(() => {});
      cancelAnimationFrame(boomFrame);
      boomFrame = requestAnimationFrame(boomerang);
    }
    function stopLockVideo() {
      cancelAnimationFrame(boomFrame);
      boomFrame = 0;
      lockVideo.pause();
    }
    function tickClock() {
      const now = new Date();
      const time = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      document.getElementById("mb-time").textContent = time;
      document.getElementById("mb-date").textContent = now.toLocaleDateString([], { weekday: "short", day: "numeric", month: "short" });
      document.getElementById("lock-time").textContent = time;
      document.getElementById("lock-date").textContent = now.toLocaleDateString([], { weekday: "long", day: "numeric", month: "long" });
    }
    // ======================= Accounts =======================
    // Guests: everything stays in this browser (localStorage). Signed in (accounts.js on the
    // server, username + password, HttpOnly session cookie): settings, wallpaper, userscripts,
    // favorite and played games are also saved to the account and loaded on any device.
    // Static build: accounts live only in this browser. Passwords are kept as a salted
    // PBKDF2 hash, and each account keeps its own saved settings ("prefs").
    const LOCAL_ACCOUNTS_KEY = "ghettoos-local-accounts", LOCAL_SESSION_KEY = "ghettoos-local-session";
    async function localApi(path, body, method) {
      body ||= {};
      const fail = (status, error) => { throw Object.assign(new Error(error), { status }); };
      let db = {};
      try { db = JSON.parse(localStorage.getItem(LOCAL_ACCOUNTS_KEY) || "{}") || {}; } catch {}
      const save = () => { try { localStorage.setItem(LOCAL_ACCOUNTS_KEY, JSON.stringify(db)); } catch { fail(507, "Not enough storage space on this device."); } };
      const k = (n) => String(n).toLowerCase();
      const setSession = (n) => { try { n ? localStorage.setItem(LOCAL_SESSION_KEY, n) : localStorage.removeItem(LOCAL_SESSION_KEY); } catch {} };
      const me = () => { try { return db[k(localStorage.getItem(LOCAL_SESSION_KEY) || "")] || null; } catch { return null; } };
      const hash = async (password, salt) => {
        if (!crypto.subtle) fail(500, "This browser can't create accounts on this page.");
        const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(password), "PBKDF2", false, ["deriveBits"]);
        const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt: new TextEncoder().encode(salt), iterations: 150000 }, key, 256);
        return [...new Uint8Array(bits)].map((b) => b.toString(16).padStart(2, "0")).join("");
      };
      switch (`${method} ${path}`) {
        case "GET /api/auth/me": return { name: me()?.name ?? null, admin: false };
        case "POST /api/auth/register": {
          const name = String(body.name || ""), password = String(body.password || "");
          if (!/^[A-Za-z0-9_.-]{3,20}$/.test(name)) fail(400, "Usernames are 3–20 letters, numbers, dots, dashes or underscores.");
          if (/^guest$/i.test(name)) fail(400, "That username is reserved.");
          if (password.length < 6 || password.length > 200) fail(400, "Passwords need at least 6 characters.");
          if (db[k(name)]) fail(409, "That username is already used on this device.");
          const salt = [...crypto.getRandomValues(new Uint8Array(16))].map((b) => b.toString(16).padStart(2, "0")).join("");
          db[k(name)] = { name, salt, hash: await hash(password, salt), prefs: null };
          save();
          setSession(name);
          return { name };
        }
        case "POST /api/auth/login": {
          const u = db[k(body.name || "")];
          if (!u || (await hash(String(body.password || ""), u.salt)) !== u.hash) fail(401, "Wrong username or password.");
          setSession(u.name);
          return { name: u.name };
        }
        case "POST /api/auth/logout": setSession(null); return { ok: true };
        case "GET /api/prefs": { const u = me() || fail(401, "Sign in first."); return { prefs: u.prefs }; }
        case "PUT /api/prefs": { const u = me() || fail(401, "Sign in first."); u.prefs = body; save(); return { ok: true }; }
      }
      fail(503, "This needs the GhettoOS server, so it isn't available in this version.");
    }
    async function api(path, body, method = body ? "POST" : "GET") {
      if (STATIC) return localApi(path, body, method);
      const send = () => fetch(path, {
        method,
        headers: body ? { "content-type": "application/json" } : {},
        body: body ? JSON.stringify(body) : undefined,
      });
      let r;
      try { r = await send(); }
      catch {
        // Network error (or a service-worker hiccup): try once more if repeating is harmless.
        try {
          if (method !== "GET" && path !== "/api/auth/login") throw 0;
          await new Promise((ok) => setTimeout(ok, 600));
          r = await send();
        } catch { throw Object.assign(new Error("Can't reach GhettoOS."), { network: true }); }
      }
      let data = {};
      try { data = await r.json(); } catch {}
      if (!r.ok) {
        // A missing /api route means the server is older than this page.
        const msg = data.error || (r.status === 404 && path.startsWith("/api/") ? "This feature isn't available yet. The server needs a restart to get the latest update." : `Request failed (${r.status}).`);
        throw Object.assign(new Error(msg), { status: r.status });
      }
      return data;
    }
    const SYNCED_SETTINGS = Object.keys(DEFAULTS).filter((k) => k !== "userName");
    function collectPrefs() {
      const s = {};
      for (const k of SYNCED_SETTINGS) s[k] = settings[k];
      return { v: 1, settings: s, userscripts, favorites: [...favorites], played, notes };
    }
    function queueSync() {
      if (!account) return;
      clearTimeout(syncTimer);
      syncTimer = setTimeout(() => api("/api/prefs", collectPrefs(), "PUT").catch((e) => console.warn("Couldn't save settings to your account:", e.message)), 1000);
    }
    function writeLocal() {
      try {
        localStorage.setItem("proxyos-settings", JSON.stringify(settings));
        localStorage.setItem(USERSCRIPTS_KEY, JSON.stringify(userscripts));
        localStorage.setItem(FAV_KEY, JSON.stringify([...favorites]));
        localStorage.setItem(PLAYED_KEY, JSON.stringify(played));
        localStorage.setItem(NOTES_KEY, JSON.stringify(notes));
      } catch {}
    }
    function applyPrefs(p) {
      const s = p.settings || {};
      const needsReload = ["engine", "transport", "wisp"].some((k) => k in s && s[k] !== settings[k]);
      for (const k of SYNCED_SETTINGS) if (k in s) settings[k] = s[k];
      if (Array.isArray(p.userscripts)) userscripts = p.userscripts;
      if (Array.isArray(p.favorites)) favorites = new Set(p.favorites);
      if (Array.isArray(p.played)) played = p.played;
      if (Array.isArray(p.notes)) { notes = p.notes; notesChanged(); }
      writeLocal();
      if (needsReload) return location.reload(); // a different proxy engine needs a fresh start
      applyAppearance();
      applyCloak();
      syncAdblock();
    }
    // Server copy wins. A brand-new account starts from whatever this device has set up.
    async function loadAccountPrefs() {
      const { prefs } = await api("/api/prefs");
      if (prefs) applyPrefs(prefs);
      else await api("/api/prefs", collectPrefs(), "PUT");
    }
    function setAccount(name) {
      account = name || null;
      showUser();
      renderLock();
      // One app failing to refresh must never break signing in.
      for (const f of [...onAccountChange]) { try { f(); } catch (e) { console.error("account change:", e); } }
    }
    // Eye button that shows / hides a password field.
    const EYE = ``;
    const EYE_OFF = ``;
    function addEye(input) {
      let wrap = input.parentElement;
      if (!wrap.classList.contains("pill-wrap")) {
        wrap = Object.assign(document.createElement("span"), { className: "eye-wrap" });
        input.replaceWith(wrap);
        wrap.append(input);
      }
      const b = Object.assign(document.createElement("button"), { type: "button", className: "pass-eye" });
      b.onmousedown = (e) => e.preventDefault(); // keep typing in the field
      const show = (on) => {
        input.type = on ? "text" : "password";
        b.innerHTML = `${on ? EYE_OFF : EYE}`;
        b.title = on ? "Hide password" : "Show password";
        b.setAttribute("aria-label", b.title);
        b.setAttribute("aria-pressed", on);
      };
      b.onclick = () => show(input.type === "password");
      input.hidePassword = () => show(false);
      show(false);
      input.after(b);
    }
    function errText(err) {
      if (err.network) return "Can't reach GhettoOS. Check your connection, or continue as guest.";
      return err.status === undefined ? `Something went wrong: ${err.message}` : err.message;
    }
    async function signIn(name, password, create) {
      const before = account;
      const { name: signedIn } = await api(create ? "/api/auth/register" : "/api/auth/login", { name, password });
      if (before && before.toLowerCase() !== signedIn.toLowerCase()) return location.reload(); // switched user
      setAccount(signedIn);
      if (!before) await loadAccountPrefs().catch((e) => console.warn("Couldn't load your settings:", e.message));
    }
    async function signOut() {
      try { await api("/api/auth/logout", {}); } catch {}
      // Don't leave this account's settings behind on a shared device.
      for (const k of ["proxyos-settings", USERSCRIPTS_KEY, FAV_KEY, PLAYED_KEY, HISTORY_KEY, NOTES_KEY]) { try { localStorage.removeItem(k); } catch {} }
      location.reload();
    }

    // ======================= Lock screen: sign in / create account / guest =======================
    const $id = (id) => document.getElementById(id);
    let lockMode = "signin"; // "signin" | "signup" (guests only)
    function lockMsg(text, isErr) { $id("lock-msg").textContent = text || ""; $id("lock-msg").classList.toggle("err", !!isErr); }
    function renderLock() {
      const user = $id("lock-user"), pass = $id("lock-pass");
      const signup = !account && lockMode === "signup";
      user.readOnly = !!account;
      if (account) user.value = account;
      $id("lock-name").textContent = account ? "Welcome back" : signup ? "Create your account" : "GhettoOS";
      pass.placeholder = signup ? "Choose a password (6+ characters)" : "Password";
      pass.autocomplete = signup ? "new-password" : "current-password";
      document.querySelector(".pill-go").title = account ? "Unlock" : signup ? "Create account" : "Sign in";
      $id("lock-mode").textContent = account ? "Sign out" : signup ? "I already have an account" : "Create account";
      $id("lock-guest").hidden = !!account;
      $id("lock-guest").previousElementSibling.hidden = !!account;
      lockMsg(account ? "Enter your password to unlock." : signup ? "Usernames are 3–20 letters, numbers, dots, dashes or underscores." : "");
    }
    $id("lock-mode").onclick = () => {
      if (account) return signOut();
      lockMode = lockMode === "signup" ? "signin" : "signup";
