    };
    $id("lock-guest").onclick = () => unlock();
    $id("lock-form").addEventListener("submit", async (e) => {
      e.preventDefault();
      const name = account || $id("lock-user").value.trim(), pass = $id("lock-pass").value;
      if (!name || !pass) return lockMsg(account ? "Enter your password." : "Enter a username and password, or continue as guest.", true);
      const card = $id("lock-form");
      card.classList.add("busy");
      try {
        await signIn(name, pass, !account && lockMode === "signup");
        lockMode = "signin";
        unlock();
      } catch (err) {
        console.error("sign in:", err);
        lockMsg(errText(err), true);
        $id("lock-pass").select();
      } finally { card.classList.remove("busy"); }
    });

    // One-liners at the bottom of the lock screen: a random one each time, then a new one every 7 s.
    const TAGLINES = ["in the gallows or the ghettos 👀", "un grr un que", "blue goo", "red goo", "green goo"];
    let taglineIdx = -1, taglineTimer = 0;
    function nextTagline() {
      let i;
      do { i = Math.floor(Math.random() * TAGLINES.length); } while (TAGLINES.length > 1 && i === taglineIdx);
      taglineIdx = i;
      const t = $id("tagline");
      if (!t.textContent) { t.textContent = TAGLINES[i]; return; }
      t.classList.add("out");
      setTimeout(() => { t.textContent = TAGLINES[i]; t.classList.remove("out"); }, 500);
    }

    function lockScreen() {
      lockEl.classList.remove("unlocking");
      lockEl.hidden = false;
      $id("lock-pass").value = "";
      $id("lock-pass").hidePassword?.();
      renderLock();
      startLockVideo();
      nextTagline();
      clearInterval(taglineTimer);
      taglineTimer = setInterval(nextTagline, 7000);
      setTimeout(() => $id(account || $id("lock-user").value ? "lock-pass" : "lock-user").focus(), 50);
    }
    function unlock() {
      lockEl.classList.add("unlocking");
      stopLockVideo();
      clearInterval(taglineTimer);
      setTimeout(() => { lockEl.hidden = true; }, 450);
    }

    // ======================= Chat (one room for every signed-in user) =======================
    // Messages arrive over Server-Sent Events (/api/chat/stream); EventSource reconnects by itself
    // and the server resends anything missed (Last-Event-ID).
    // Sign-in form shown inside account-only apps (Chat, Inbox).
    function authPrompt(el, title, text) {
      el.innerHTML = `










Sign inCreate account
      `;
      const f = el.querySelector("form");
      f.querySelector(".logo-img").src = ORIGINAL.icon;
      f.querySelector("h2").textContent = title;
      f.querySelector("p").textContent = text;
      const go = async (create) => {
        const u = f.u.value.trim(), p = f.p.value;
        if (!u || !p) return (f.querySelector(".msg").textContent = "Enter a username and password.");
        f.classList.add("busy");
        try { await signIn(u, p, create); } // success re-renders through onAccountChange
        catch (e) { console.error("sign in:", e); f.querySelector(".msg").textContent = errText(e); }
        finally { f.classList.remove("busy"); }
