      f.querySelector("[data-create]").onclick = () => go(true);
      addEye(f.p);
      setTimeout(() => f.u.focus(), 50);
    }

    // ---- Small shared UI: toast, pop-up menu, emoji rows, message rows ----
    const nameHue = (s) => { let h = 0; for (const c of s.toLowerCase()) h = (h * 31 + c.charCodeAt(0)) >>> 0; return h % 360; };
    function avatar(name, cls = "av") {
      const a = Object.assign(document.createElement("span"), { className: cls, textContent: name[0].toUpperCase() });
      a.style.background = `hsl(${nameHue(name)} 45% 38%)`;
      return a;
    }
    let toastTimer = 0;
    function toast(text) {
      let t = document.querySelector(".toast");
