      t.textContent = text;
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => t.remove(), 2600);
    }
    let ctxEl = null, ctxOnClose = null;
    function closeMenu() {
      ctxEl?.remove();
      ctxEl = null;
      const f = ctxOnClose;
      ctxOnClose = null;
      f?.();
    }
    function showMenu(x, y, build, onClose) {
      closeMenu();
      const m = Object.assign(document.createElement("div"), { className: "ctx-menu", role: "menu" });
      build(m);
      document.body.append(m);
      const r = m.getBoundingClientRect();
      m.style.left = Math.max(6, Math.min(x, innerWidth - r.width - 6)) + "px";
      m.style.top = Math.max(6, Math.min(y, innerHeight - r.height - 6)) + "px";
