    document.addEventListener("pointerdown", (e) => { if (ctxEl && !ctxEl.contains(e.target)) closeMenu(); }, true);
    document.addEventListener("keydown", (e) => { if (e.key === "Escape" && ctxEl) closeMenu(); });
    function menuItem(label, fn, cls = "") {
