    }
    const menuSep = () => document.createElement("hr");
    const REACTIONS = ["👍", "❤️", "😂", "😮", "😢", "🔥"];
    const EMOJIS = ["😀", "😂", "🤣", "😊", "😍", "😎", "🤔", "😭", "😅", "😇", "🥺", "😤", "😡", "🤯", "😱", "😴",
      "💀", "🤡", "🗿", "🫡", "👀", "👋", "👍", "👎", "👏", "🙏", "💪", "🤝", "🔥", "❤️", "💔", "✨",
      "🎉", "💯", "✅", "❌", "⭐", "🎮", "🍕", "🎵"];
    // A row of emoji buttons. keepOpen: picking doesn't close the menu (emoji picker).
    function emojiRow(list, pick, { grid = false, keepOpen = false } = {}) {
      const box = Object.assign(document.createElement("div"), { className: "emojis" + (grid ? " grid" : "") });
      for (const emo of list) {
        const b = Object.assign(document.createElement("button"), { type: "button", textContent: emo, title: emo });
        b.onmousedown = (e) => e.preventDefault(); // keep focus in the text box
        b.onclick = () => { if (!keepOpen) closeMenu(); pick(emo); };
        box.append(b);
      }
      return box;
    }
    // Emoji picker for a text input (stays open so several can be added).
    function emojiPicker(btn, input) {
      const r = btn.getBoundingClientRect();
      showMenu(r.left, r.top - 240, (m) => m.append(emojiRow(EMOJIS, (emo) => {
        const s = input.selectionStart ?? input.value.length, e = input.selectionEnd ?? s;
        if (input.value.length + emo.length > input.maxLength) return;
        input.setRangeText(emo, s, e, "end");
        input.focus();
      }, { grid: true, keepOpen: true })));
    }
    // Avatar + name + time + text (Chat and Inbox). cont = same person a moment ago.
    function msgRow(name, created, text, cont) {
      const row = document.createElement("div");
      row.className = "chat-msg" + (cont ? " cont" : "") + (name === account ? " mine" : "");
      row.innerHTML = `



`;
      row.prepend(avatar(name, "avatar"));
      if (cont) row.querySelector(".who").remove();
      else {
        row.querySelector("b").textContent = name;
        const t = new Date(created);
        const time = row.querySelector("time");
        time.textContent = t.toDateString() === new Date().toDateString()
          ? t.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
          : t.toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
        time.dateTime = t.toISOString();
      }
      row.querySelector(".text").textContent = text;
      return row;
    }

    // ======================= Friends, blocks, unread DMs (signed in) =======================
    // One SSE connection per signed-in page (/api/inbox/stream) keeps the Inbox badge and lists live.
    const EMPTY_SOCIAL = { friends: [], incoming: [], outgoing: [], blocked: [] };
    let social = EMPTY_SOCIAL, unread = {}, inboxES = null;
    const socialBus = new EventTarget(); // events: "social", "dm" (ev.data; a listener sets ev.seen)
    const lc = (s) => s.toLowerCase();
    const isBlocked = (name) => social.blocked.some((n) => lc(n) === lc(name));
    function updateInboxBadge() {
      setDeskBadge("Inbox", Object.values(unread).reduce((a, b) => a + b, 0) + social.incoming.length);
    }
    function socialChanged(next) {
      social = next;
      socialBus.dispatchEvent(new Event("social"));
      updateInboxBadge();
    }
    const refreshSocial = () => account && api("/api/social").then(socialChanged, () => {});
    async function socialAct(action, name) {
      try { socialChanged(await api("/api/social", { action, name })); return true; }
      catch (e) { toast(e.message); return false; }
    }
    function connectInbox() {
      inboxES?.close();
      inboxES = null;
      unread = {};
      socialChanged(EMPTY_SOCIAL);
      if (!account || STATIC) return;
      refreshSocial();
      inboxES = new EventSource("/api/inbox/stream");
      inboxES.onmessage = (e) => {
        const d = JSON.parse(e.data);
        if (d.type === "unread") { unread = d.unread; updateInboxBadge(); }
        else if (d.type === "social") refreshSocial();
        else if (d.type === "dm") {
          const ev = Object.assign(new Event("dm"), { data: d, seen: false });
          socialBus.dispatchEvent(ev);
          if (lc(d.from) !== lc(account) && !ev.seen) { unread[d.from] = (unread[d.from] || 0) + 1; updateInboxBadge(); toast(`💬 ${d.from}: ${d.text}`.slice(0, 90)); }
        }
      };
    }
    onAccountChange.add(connectInbox);
    // "Add friend" menu item that matches where you stand with them.
    function friendItem(name) {
      const has = (list) => list.some((n) => lc(n) === lc(name));
      if (has(social.friends)) return Object.assign(menuItem("✓ Friends", () => {}), { disabled: true });
      if (has(social.outgoing)) return Object.assign(menuItem("Friend request sent", () => {}), { disabled: true });
      return menuItem(has(social.incoming) ? "Accept friend request" : "Add friend", async () => {
        if (await socialAct("add", name)) toast(social.friends.some((n) => lc(n) === lc(name)) ? `You and ${name} are friends now` : `Friend request sent to ${name}`);
      });
    }
    async function confirmBlock(name) {
      if (!confirm(`Block ${name}?\n\nYou won't see their chat messages, and they can't message you or add you. You can unblock them in Inbox.`)) return;
      if (await socialAct("block", name)) toast(`Blocked ${name}`);
    }

    // Time on GhettoOS: a heartbeat every minute while the page is visible (signed in only).
    function beat() { if (account && !STATIC && !document.hidden) return api("/api/activity", {}).catch(() => {}); }
    setInterval(beat, 60e3);
    onAccountChange.add(beat);

    function openChat() {
      const el = document.createElement("div");
      el.className = "app chat-app";
      let es = null, offSocial = null;
      const stop = () => { es?.close(); es = null; offSocial?.(); offSocial = null; };
      const render = () => {
        stop();
        if (!el.isConnected && onAccountChange.has(render)) return onAccountChange.delete(render); // window closed
        account ? renderRoom() : authPrompt(el, "Sign in to chat", "Chat is shared by everyone on GhettoOS. Sign in, or create an account with a username and password.");
      };

      function renderRoom() {
        el.innerHTML = `
# everyoneconnecting…


Loading messages…



✕
          🙂Send`;
        const log = el.querySelector(".chat-log"), note = el.querySelector(".chat-note"), online = el.querySelector(".online");
        const form = el.querySelector("form"), input = form.querySelector("input"), sendBtn = form.querySelector('[type="submit"]');
        const replyBar = el.querySelector(".chat-reply");
        const byId = new Map(); // id -> { m, row }
        let last = null, replyTo = null;
        form.querySelector(".emoji-btn").onclick = (e) => emojiPicker(e.currentTarget, input);

        function setReply(m) {
          replyTo = m;
          replyBar.hidden = !m;
          if (!m) return;
          const s = replyBar.querySelector("span");
          s.innerHTML = "Replying to : ";
          s.querySelector("b").textContent = m.name;
          s.append(m.text);
          input.focus();
        }
        replyBar.querySelector("button").onclick = () => setReply(null);
        const hideBlocked = (row) => row.classList.toggle("blocked", isBlocked(row.dataset.name));
        const onSocial = () => log.querySelectorAll(".chat-msg").forEach(hideBlocked);
        socialBus.addEventListener("social", onSocial);
        offSocial = () => socialBus.removeEventListener("social", onSocial);

        const react = (id, emoji) => api("/api/chat/react", { id, emoji }).catch((e) => (note.textContent = e.message));
        function setReactions(id, reactions) {
          const it = byId.get(id);
          if (!it) return;
          it.m.reactions = reactions;
          const box = it.row.querySelector(".reacts");
          box.textContent = "";
          for (const [emo, names] of Object.entries(reactions)) {
            const b = Object.assign(document.createElement("button"), { type: "button", textContent: `${emo} ${names.length}`, title: names.join(", ") });
            if (names.includes(account)) b.className = "on";
            b.onclick = () => react(id, emo);
            box.append(b);
          }
        }
        function jumpTo(id) {
          const it = byId.get(id);
          if (!it) return toast("That message is too old to show here.");
          it.row.scrollIntoView({ block: "center", behavior: "smooth" });
          it.row.classList.add("flash");
          setTimeout(() => it.row.classList.remove("flash"), 1200);
        }
        function msgMenu(m, row, x, y) {
          row.classList.add("menu-open");
          showMenu(x, y, (menu) => {
            menu.append(emojiRow(REACTIONS, (emo) => react(m.id, emo)), menuSep(),
              menuItem("↩  Reply", () => setReply(m)),
              menuItem("Copy text", () => navigator.clipboard?.writeText(m.text).catch(() => {})));
            if (lc(m.name) !== lc(account)) menu.append(menuSep(), friendItem(m.name), menuItem(`Block ${m.name}`, () => confirmBlock(m.name), "danger"));
          }, () => row.classList.remove("menu-open"));
        }
        function addMsg(m) {
          if (byId.has(m.id)) return;
          log.querySelector(".chat-empty")?.remove();
          const stick = log.scrollHeight - log.scrollTop - log.clientHeight < 60;
          const cont = last && last.name === m.name && m.created - last.created < 5 * 60e3 && !m.reply;
          const row = msgRow(m.name, m.created, m.text, cont);
          row.dataset.name = m.name;
          if (m.reply) {
            const q = Object.assign(document.createElement("button"), { type: "button", className: "quote", title: "Show the original message" });
            q.innerHTML = "↪  ";
            q.querySelector("b").textContent = m.reply.name;
            q.append(m.reply.text);
            q.onclick = () => jumpTo(m.reply.id);
            row.querySelector(".text").before(q);
          }
          const acts = Object.assign(document.createElement("div"), { className: "acts" });
          acts.innerHTML = `🙂↩⋯`;
          acts.querySelector('[data-a="react"]').onclick = (e) => {
            const r = e.currentTarget.getBoundingClientRect();
            row.classList.add("menu-open");
            showMenu(r.left - 90, r.bottom + 4, (menu) => menu.append(emojiRow(REACTIONS, (emo) => react(m.id, emo))), () => row.classList.remove("menu-open"));
          };
          acts.querySelector('[data-a="reply"]').onclick = () => setReply(m);
          acts.querySelector('[data-a="more"]').onclick = (e) => { const r = e.currentTarget.getBoundingClientRect(); msgMenu(m, row, r.right - 190, r.bottom + 4); };
          row.append(acts);
          row.oncontextmenu = (e) => { e.preventDefault(); msgMenu(m, row, e.clientX, e.clientY); };
          hideBlocked(row);
          log.append(row);
          byId.set(m.id, { m, row });
          setReactions(m.id, m.reactions || {});
          last = m;
          if (stick || m.name === account) log.scrollTop = log.scrollHeight;
        }
        es = new EventSource("/api/chat/stream");
        es.onopen = () => { note.textContent = ""; };
        es.onmessage = (e) => {
          const d = JSON.parse(e.data);
          if (d.type === "msg") addMsg(d);
          else if (d.type === "react") setReactions(d.id, d.reactions);
          else if (d.type === "online") {
            online.textContent = `${d.names.length} online`;
            online.title = d.names.join(", ");
            const empty = log.querySelector(".chat-empty");
            if (empty) empty.textContent = "No messages yet. Say hi 👋";
          }
        };
        es.onerror = () => {
          if (es?.readyState === EventSource.CLOSED) { // server refused: probably signed out elsewhere
            api("/api/auth/me").then(({ name }) => { if (!name) setAccount(null); else note.textContent = "Chat disconnected. Close and reopen it to retry."; }).catch(() => {});
          } else note.textContent = "Reconnecting…";
        };
        form.onsubmit = async (e) => {
          e.preventDefault();
          const text = input.value.trim();
          if (!text) return;
          sendBtn.disabled = true;
          try { await api("/api/chat/send", { text, replyTo: replyTo?.id ?? null }); input.value = ""; note.textContent = ""; setReply(null); }
          catch (err) { note.textContent = err.status === 401 ? "Your session ended. Sign in again." : err.message; if (err.status === 401) setAccount(null); }
          finally { sendBtn.disabled = false; input.focus(); }
        };
        setTimeout(() => input.focus(), 50);
      }

      openWindow("Chat", el, {
        app: "Chat",
        width: Math.min(520, Math.round(innerWidth * 0.9)),
        height: Math.round((innerHeight - MENU_H - dockSpace()) * 0.85),
        onclose: () => { stop(); onAccountChange.delete(render); },
      });
      onAccountChange.add(render);
      render();
    }

    const appHeight = (f) => Math.round((innerHeight - MENU_H - dockSpace()) * f);

    // ======================= Inbox (friends + direct messages) =======================
    function openInbox() {
      const el = document.createElement("div");
      el.className = "app";
      let sel = null, offs = [];
      const cleanup = () => { offs.forEach((f) => f()); offs = []; };
      const on = (type, fn) => { socialBus.addEventListener(type, fn); offs.push(() => socialBus.removeEventListener(type, fn)); };
      const render = () => {
        cleanup();
        if (!el.isConnected && onAccountChange.has(render)) return onAccountChange.delete(render);
        sel = null;
        if (!account) { el.className = "app"; return authPrompt(el, "Sign in to use Inbox", "Add friends and message them privately. Sign in, or create an account."); }
        el.className = "app inbox";
        renderInbox();
      };

      function renderInbox() {
        el.innerHTML = `

            Add






`;
        const side = el.querySelector(".lists"), main = el.querySelector(".inbox-main"), msg = el.querySelector(".inbox-msg");
        const addForm = el.querySelector(".inbox-add"), addInput = addForm.querySelector("input");
        const say = (t, err) => { msg.textContent = t; msg.classList.toggle("err", !!err); };
        addForm.onsubmit = async (e) => {
          e.preventDefault();
          const name = addInput.value.trim();
          if (!name) return;
          try {
            socialChanged(await api("/api/social", { action: "add", name }));
            addInput.value = "";
            const friend = social.friends.find((n) => lc(n) === lc(name));
            say(friend ? `You and ${friend} are friends now.` : `Friend request sent.`);
          } catch (err) { say(err.message, true); }
        };

        function section(title, names, build) {
          const h = Object.assign(document.createElement("h4"), { textContent: title });
          side.append(h);
          if (!names.length) return side.append(Object.assign(document.createElement("div"), { className: "none", textContent: title === "Friends" ? "No friends yet." : "None" }));
          for (const n of names) side.append(build(n));
        }
        const mini = (label, fn, cls = "") => {
          const b = Object.assign(document.createElement("button"), { type: "button", className: "mini " + cls, textContent: label });
          b.onclick = (e) => { e.stopPropagation(); fn(); };
          return b;
        };
        const person = (name, tag = "div") => {
          const p = Object.assign(document.createElement(tag), { className: "person" });
          if (tag === "button") p.type = "button";
          p.append(avatar(name, "av sm"), Object.assign(document.createElement("span"), { className: "nm", textContent: name }));
          return p;
        };
        function drawLists() {
          side.textContent = "";
          if (social.incoming.length) section("Friend requests", social.incoming, (n) => {
            const p = person(n);
            p.append(mini("Accept", () => socialAct("add", n), "ok"), mini("✕", () => socialAct("remove", n)));
            return p;
          });
          section("Friends", social.friends, (n) => {
            const p = person(n, "button");
            if (sel && lc(sel) === lc(n)) p.classList.add("sel");
            if (unread[n]) p.append(Object.assign(document.createElement("span"), { className: "badge", textContent: unread[n] }));
            p.onclick = () => openThread(n);
            p.oncontextmenu = (e) => { e.preventDefault(); friendMenu(n, e.clientX, e.clientY); };
            return p;
          });
          if (social.outgoing.length) section("Sent requests", social.outgoing, (n) => {
            const p = person(n);
            p.append(mini("Cancel", () => socialAct("remove", n)));
            return p;
          });
          if (social.blocked.length) section("Blocked", social.blocked, (n) => {
            const p = person(n);
            p.append(mini("Unblock", () => socialAct("unblock", n)));
            return p;
          });
        }
        function friendMenu(n, x, y) {
          showMenu(x, y, (m) => m.append(
            menuItem("Message", () => openThread(n)),
            menuItem("Remove friend", () => { if (confirm(`Remove ${n} from your friends?`)) socialAct("remove", n); }),
            menuSep(),
            menuItem(`Block ${n}`, () => confirmBlock(n), "danger")));
        }
        function showEmpty() {
          sel = null;
          main.innerHTML = `
Pick a friend to start chatting.

Add people by username on the left,
or right-click someone's message in Chat.`;
        }

        let threadIds = new Set(), last = null, log = null;
        function addDm(m) {
          if (threadIds.has(m.id)) return;
          threadIds.add(m.id);
          log.querySelector(".chat-empty")?.remove();
          const cont = last && last.from === m.from && m.created - last.created < 5 * 60e3;
          log.append(msgRow(m.from, m.created, m.text, cont));
          last = m;
          log.scrollTop = log.scrollHeight;
        }
        async function openThread(name) {
          sel = name;
          threadIds = new Set();
          last = null;
          main.innerHTML = `
⋯


Loading…


            🙂Send`;
          const top = main.querySelector(".chat-top");
          top.prepend(avatar(name, "av sm"));
          top.querySelector("b").textContent = name;
          top.querySelector(".gbtn").onclick = (e) => { const r = e.currentTarget.getBoundingClientRect(); friendMenu(name, r.right - 190, r.bottom + 4); };
          log = main.querySelector(".chat-log");
          const note = main.querySelector(".chat-note"), form = main.querySelector("form"), input = form.querySelector("input"), sendBtn = form.querySelector('[type="submit"]');
          input.placeholder = `Message ${name}`;
          form.querySelector(".emoji-btn").onclick = (e) => emojiPicker(e.currentTarget, input);
          delete unread[name];
          updateInboxBadge();
          drawLists();
          form.onsubmit = async (e) => {
            e.preventDefault();
            const text = input.value.trim();
            if (!text) return;
            sendBtn.disabled = true;
            try { await api("/api/dm", { to: name, text }); input.value = ""; note.textContent = ""; }
            catch (err) { note.textContent = err.message; }
            finally { sendBtn.disabled = false; input.focus(); }
          };
          setTimeout(() => input.focus(), 50);
          try {
            const { messages } = await api(`/api/dm?with=${encodeURIComponent(name)}`);
            if (sel !== name) return;
            if (!messages.length) log.querySelector(".chat-empty").textContent = `This is the start of your messages with ${name}. Say hi 👋`;
            messages.forEach(addDm);
          } catch (err) { note.textContent = err.message; }
        }

        on("social", () => {
          drawLists();
          if (sel && !social.friends.some((n) => lc(n) === lc(sel))) showEmpty(); // unfriended / blocked
        });
        on("dm", (ev) => {
          const d = ev.data, other = lc(d.from) === lc(account) ? d.to : d.from;
          if (!sel || lc(other) !== lc(sel) || !log) return drawLists();
          addDm(d);
          if (lc(d.from) !== lc(account)) { ev.seen = true; api("/api/dm/read", { with: other }).catch(() => {}); }
        });
        drawLists();
        showEmpty();
        refreshSocial();
      }

      openWindow("Inbox", el, { app: "Inbox", width: Math.min(720, Math.round(innerWidth * 0.92)), height: appHeight(0.85), onclose: () => { cleanup(); onAccountChange.delete(render); } });
      onAccountChange.add(render);
      render();
    }

    // ======================= Leaderboard (day streaks + time spent) =======================
    const fmtDuration = (s) => { const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60); return s < 60 ? "<1m" : h ? `${h}h ${m}m` : `${m}m`; };
    function openLeaderboard() {
      const el = document.createElement("div");
      el.className = "app";
      el.innerHTML = `

🔥 Day streak⏱ Time spentRefresh



Loading…`;
      const me = el.querySelector(".lb-me"), list = el.querySelector(".lb-list");
      let tab = "streak", data = null;
      el.querySelectorAll("[data-t]").forEach((b) => (b.onclick = () => {
        tab = b.dataset.t;
        el.querySelectorAll("[data-t]").forEach((x) => x.classList.toggle("on", x === b));
        draw();
      }));
      function draw() {
        if (!data) return;
        if (account && data.me) me.innerHTML = `
${data.me.streak}day streak
${data.me.best}best streak
${fmtDuration(data.me.seconds)}time on GhettoOS`;
        else me.textContent = account ? "Your stats show up after your first minute online." : "Sign in to get on the leaderboard. Come back every day to grow your streak!";
        const rows = tab === "streak" ? data.streak : data.time;
        list.textContent = "";
        if (!rows.length) return list.append(Object.assign(document.createElement("li"), { className: "lb-note", textContent: "Nobody here yet. Be the first!" }));
        rows.forEach((r, i) => {
          const li = document.createElement("li");
          if (account && lc(r.name) === lc(account)) li.className = "me";
          const rank = Object.assign(document.createElement("span"), { className: "rank" + (i < 3 ? " medal" : ""), textContent: i < 3 ? ["🥇", "🥈", "🥉"][i] : i + 1 });
          const val = Object.assign(document.createElement("span"), { className: "val" });
          if (tab === "streak") {
            val.textContent = `${r.streak} day${r.streak === 1 ? "" : "s"}`;
            val.append(Object.assign(document.createElement("span"), { className: "sub", textContent: `best ${r.best}` }));
          } else val.textContent = fmtDuration(r.seconds);
          li.append(rank, avatar(r.name, "av sm"), Object.assign(document.createElement("span"), { className: "nm", textContent: r.name }), val);
          list.append(li);
        });
      }
      async function load() {
        try { await beat(); data = await api("/api/leaderboard"); draw(); }
        catch (e) { list.innerHTML = ""; list.append(Object.assign(document.createElement("li"), { className: "lb-note", textContent: e.status === undefined ? "Can't reach GhettoOS right now." : e.message })); }
      }
      el.querySelector("[data-r]").onclick = load;
      const onAcct = () => (el.isConnected ? load() : onAccountChange.delete(onAcct));
      onAccountChange.add(onAcct);
      openWindow("Leaderboard", el, { app: "Leaderboard", width: Math.min(460, Math.round(innerWidth * 0.92)), height: appHeight(0.85), onclose: () => onAccountChange.delete(onAcct) });
      load();
    }

    // ======================= Calculator =======================
    function openCalculator() {
      const el = document.createElement("div");
      el.className = "app calc";
      el.tabIndex = 0;
      el.innerHTML = `

0

        AC±%÷
        789×
        456−
        123+
        0.=`;
      const disp = el.querySelector(".calc-display"), exprEl = el.querySelector(".calc-expr");
      const SYM = { "/": "÷", "*": "×", "-": "−", "+": "+" };
      let cur = "0", acc = null, op = null, fresh = true, expr = "";
      const calc = (a, b, o) => (o === "+" ? a + b : o === "-" ? a - b : o === "*" ? a * b : b === 0 ? NaN : a / b);
      const fmt = (n) => (Number.isFinite(n) ? String(parseFloat(n.toPrecision(12))) : "Error");
      function press(k) {
        if (/^\d$/.test(k)) { if (fresh || cur === "0" || cur === "Error") cur = k; else if (cur.replace(/[-.]/g, "").length < 15) cur += k; fresh = false; expr = op ? expr : ""; }
        else if (k === ".") { if (fresh || cur === "Error") { cur = "0."; fresh = false; } else if (!cur.includes(".")) cur += "."; }
        else if (k === "C") { cur = "0"; acc = null; op = null; fresh = true; expr = ""; }
        else if (k === "±") { if (cur !== "0" && cur !== "Error") cur = cur.startsWith("-") ? cur.slice(1) : "-" + cur; }
        else if (k === "%") { cur = fmt(parseFloat(cur) / 100); fresh = true; }
        else if (k === "Backspace") { if (!fresh) { cur = cur.slice(0, -1); if (cur === "" || cur === "-") cur = "0"; } }
        else if (k in SYM) {
          if (op && !fresh) { acc = calc(acc, parseFloat(cur), op); cur = fmt(acc); }
          else if (!op) acc = parseFloat(cur);
          op = k; fresh = true;
          expr = `${fmt(acc)} ${SYM[op]}`;
        } else if (k === "=") {
          if (!op) return;
          const b = parseFloat(cur);
          expr = `${fmt(acc)} ${SYM[op]} ${fmt(b)} =`;
          cur = fmt(calc(acc, b, op));
          acc = null; op = null; fresh = true;
        }
        disp.textContent = cur;
        exprEl.textContent = expr;
        el.querySelectorAll(".op").forEach((b) => b.classList.toggle("on", b.dataset.k === op && fresh));
      }
      el.querySelector(".calc-keys").onclick = (e) => { const k = e.target.closest("button")?.dataset.k; if (k) press(k); };
      el.onkeydown = (e) => {
        if (e.ctrlKey || e.metaKey || e.altKey) return;
        const k = { Enter: "=", "=": "=", Escape: "C", Delete: "C", ",": ".", x: "*", X: "*" }[e.key] ?? e.key;
        if (/^[\d.%+\-*/=C]$|^Backspace$/.test(k)) { e.preventDefault(); press(k); }
      };
      openWindow("Calculator", el, { app: "Calculator", width: 300, height: 460 });
      setTimeout(() => el.focus(), 50);
    }

    // ======================= Notepad =======================
    function openNotepad() {
      const el = document.createElement("div");
      el.className = "app notes";
      el.innerHTML = `

+ NewDelete

        `;
      const list = el.querySelector(".notes-list"), ta = el.querySelector("textarea");
      let selId = null, timer = 0, dirty = false;
      const titleOf = (n) => (n.text.trim().split("\n")[0] || "New note").slice(0, 80);
      const flush = () => { clearTimeout(timer); if (dirty) { dirty = false; saveNotes(); } };
      function drawList() {
        list.textContent = "";
        for (const n of [...notes].sort((a, b) => b.updated - a.updated)) {
          const b = Object.assign(document.createElement("button"), { type: "button", className: "note-item" + (n.id === selId ? " sel" : "") });
          b.append(Object.assign(document.createElement("b"), { textContent: titleOf(n) }),
            Object.assign(document.createElement("small"), { textContent: new Date(n.updated).toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }) }));
          b.onclick = () => { flush(); select(n.id); };
          list.append(b);
        }
      }
      function select(id) {
        selId = notes.some((n) => n.id === id) ? id : null;
        ta.value = notes.find((n) => n.id === selId)?.text ?? "";
        drawList();
      }
      function newNote() {
        flush();
        const n = { id: Date.now().toString(36) + Math.random().toString(36).slice(2, 6), text: "", updated: Date.now() };
        notes.push(n);
        select(n.id);
        ta.focus();
      }
      ta.oninput = () => {
        let n = notes.find((x) => x.id === selId);
        if (!n) { notes.push((n = { id: Date.now().toString(36), text: "", updated: 0 })); selId = n.id; }
        n.text = ta.value;
        n.updated = Date.now();
        dirty = true;
        clearTimeout(timer);
        timer = setTimeout(flush, 500);
        drawList();
      };
      el.querySelector("[data-new]").onclick = newNote;
      el.querySelector("[data-del]").onclick = () => {
        const n = notes.find((x) => x.id === selId);
        if (!n || (n.text.trim() && !confirm(`Delete “${titleOf(n)}”?`))) return;
        notes = notes.filter((x) => x !== n);
        dirty = true;
        flush();
        select([...notes].sort((a, b) => b.updated - a.updated)[0]?.id);
      };
      notesRender = () => select(selId);
      openWindow("Notepad", el, { app: "Notepad", width: Math.min(680, Math.round(innerWidth * 0.92)), height: Math.min(480, appHeight(0.85)),
        onclose: () => { flush(); notesRender = null; } });
      select([...notes].sort((a, b) => b.updated - a.updated)[0]?.id);
      setTimeout(() => ta.focus(), 50);
    }

    // ======================= Changelog =======================
    // Newest first. Add an entry for every major update (CHANGELOG[0].version is shown in About).
    // Users read this: keep it short and high-level. No technical internals, no names of
    // outside sites or services, nothing about hiding or getting around anything.
    const CHANGELOG = [
      {
        version: "1.0.0", date: "2026-11-19", title: "First release",
        groups: [
          ["Desktop", [
            "A brand-new desktop with a lock screen, menu bar, dock and movable windows.",
            "Every app is now on the desktop as well as in the dock.",
            "Wallpapers and themes to make it your own.",
          ]],
          ["Apps", [
            "Browser, Games, Chat, Inbox, Leaderboard, Calculator, Notepad and more.",
            "Your favorite sites open in their own app windows.",
            "Games: a large library with search, favorites and full screen.",
          ]],
          ["Accounts", [
            "Create an account to keep your settings, favorites and notes on any device, or continue as a guest.",
            "Make friends and send them private messages in Inbox.",
            "Reply to and react to messages in Chat.",
            "Leaderboard: daily streaks and time spent.",
          ]],
          ["Feedback", [
            "Have an idea or found a bug? Send it with the Suggestions app.",
          ]],
        ],
      },
    ];
    function openChangelog() {
      const el = document.createElement("div");
      el.className = "app changelog";
      for (const rel of CHANGELOG) {
        const sec = Object.assign(document.createElement("section"), { className: "cl-rel" });
        sec.innerHTML = ``;
        sec.querySelector(".ver").textContent = "v" + rel.version;
        sec.querySelector(".ttl").textContent = rel.title;
        sec.querySelector(".date").textContent = new Date(rel.date + "T12:00").toLocaleDateString([], { year: "numeric", month: "long", day: "numeric" });
        for (const [h, items] of rel.groups) {
          const ul = document.createElement("ul");
          for (const t of items) ul.append(Object.assign(document.createElement("li"), { textContent: t }));
          sec.append(Object.assign(document.createElement("h4"), { textContent: h }), ul);
        }
        el.append(sec);
      }
      openWindow("Changelog", el, { app: "Changelog", width: Math.min(560, Math.round(innerWidth * 0.92)), height: appHeight(0.85) });
    }

    // ======================= Suggestions =======================
    // Anyone can send one. The owner (ADMIN_USERS on the server) also sees what was sent.
    function openSuggestions() {
      const el = document.createElement("div");
      el.className = "app suggest";
      el.innerHTML = `
💡 Suggestion box

Got an idea for GhettoOS, a game or site to add, or found a bug? Write it here and it goes straight to the owner.


Send suggestion

`;
      const ta = el.querySelector("textarea"), btn = el.querySelector(".gbtn"), note = el.querySelector(".note"), received = el.querySelector(".received");
      const say = (t, err) => { note.textContent = t; note.classList.toggle("err", !!err); };
      const who = () => say(account ? `Sending as ${account}` : "Sending as a guest");
      who();
      btn.onclick = async () => {
        const text = ta.value.trim();
        if (text.length < 3) return say("Write a little more first.", true);
        btn.disabled = true;
        try { await api("/api/suggest", { text }); ta.value = ""; say("Sent! Thanks for the idea 💡"); loadReceived(); }
        catch (e) { say(e.status === undefined ? "Can't reach GhettoOS right now." : e.message, true); }
        finally { btn.disabled = false; }
      };
      async function loadReceived() {
        received.textContent = "";
        if (!account) return;
        let list;
        try { ({ suggestions: list } = await api("/api/suggestions")); } catch { return; } // not the owner
        received.append(Object.assign(document.createElement("h3"), { textContent: `Received (${list.length})` }));
        if (!list.length) received.append(Object.assign(document.createElement("p"), { textContent: "No suggestions yet." }));
        for (const s of list) {
          const item = Object.assign(document.createElement("div"), { className: "sg-item" });
          item.innerHTML = `
Delete
`;
          item.querySelector("b").textContent = s.name || "Guest";
          item.querySelector(".meta span").textContent = new Date(s.created).toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
          item.querySelector(".txt").textContent = s.text;
          item.querySelector("button").onclick = () => api("/api/suggestions/delete", { id: s.id }).then(loadReceived, (e) => say(e.message, true));
          received.append(item);
        }
      }
      const onAcct = () => { if (!el.isConnected) return onAccountChange.delete(onAcct); who(); loadReceived(); };
      onAccountChange.add(onAcct);
      openWindow("Suggestions", el, { app: "Suggestions", width: Math.min(520, Math.round(innerWidth * 0.92)), height: appHeight(0.8), onclose: () => onAccountChange.delete(onAcct) });
      loadReceived();
      setTimeout(() => ta.focus(), 50);
    }

    // ======================= AI Chat (static build) =======================
    // Without the proxy, duck.ai can't load, so the static build talks to Pollinations'
    // keyless, CORS-enabled chat API straight from the browser (slow-ish: it's rate limited).
    // Checked 2026-11: text.pollinations.ai now wants a Turnstile (human check) token from
    // browsers, and gen.pollinations.ai's keyless tier refuses custom system prompts (401).
    // Without a key only a few cached prompts work, so real questions need a free Pollinations
    // key (enter.pollinations.ai/keys). It's kept in this browser only.
    const AI_ENDPOINTS = ["https://gen.pollinations.ai/v1/chat/completions"];
    const AI_KEY = "ghettoos-ai-key";
    const aiKey = () => { try { return localStorage.getItem(AI_KEY) || ""; } catch { return ""; } };
    async function askAI(messages) {
      let lastErr;
      for (const url of AI_ENDPOINTS) {
        try {
          const headers = { "content-type": "application/json" };
          if (aiKey()) headers.authorization = "Bearer " + aiKey();
          const r = await fetch(url, { method: "POST", headers, body: JSON.stringify({ model: "openai", messages }) });
          if (r.status === 429) { lastErr = new Error("AI Chat is busy. Wait a few seconds and try again."); continue; }
          if (r.status === 401 || r.status === 403) {
            lastErr = Object.assign(new Error(aiKey() ? "That AI Chat key didn't work. Check it and try again." : "AI Chat needs a free key. Get one at enter.pollinations.ai/keys and paste it above."), { needsKey: true });
            continue;
          }
          if (!r.ok) { lastErr = new Error(`AI Chat failed (${r.status}).`); continue; }
          const text = (await r.json())?.choices?.[0]?.message?.content;
          if (text) return text.trim();
          lastErr = new Error("AI Chat sent an empty reply.");
        } catch { lastErr = new Error("Can't reach AI Chat. Check your connection."); }
      }
      throw lastErr;
    }
    function openAIChat() {
      const el = document.createElement("div");
      el.className = "app chat-app";
      el.innerHTML = `
AI ChatKeyNew chat
        Save


Ask me anything.


        Send`;
      const log = el.querySelector(".chat-log"), note = el.querySelector(".chat-note");
      const form = el.querySelector(".chat-send"), input = form.querySelector("input"), sendBtn = form.querySelector('[type="submit"]');
      let history = [];
      const keyForm = el.querySelector(".ai-key"), keyInput = keyForm.querySelector("input");
      const showKey = (on = keyForm.hidden) => { keyForm.hidden = !on; if (on) { keyInput.value = aiKey(); keyInput.focus(); } };
      el.querySelector("[data-key]").onclick = () => showKey();
      keyForm.onsubmit = (e) => {
        e.preventDefault();
        try { keyInput.value.trim() ? localStorage.setItem(AI_KEY, keyInput.value.trim()) : localStorage.removeItem(AI_KEY); } catch {}
        showKey(false);
        note.textContent = aiKey() ? "Key saved. Send your message again." : "Key removed.";
        input.focus();
      };
      const add = (who, text) => {
        log.querySelector(".chat-empty")?.remove();
        const row = msgRow(who, Date.now(), text, false);
        log.append(row);
        log.scrollTop = log.scrollHeight;
        return row;
      };
      el.querySelector("[data-new]").onclick = () => {
        history = [];
        note.textContent = "";
        log.innerHTML = `
Ask me anything.`;
        input.focus();
      };
      form.onsubmit = async (e) => {
        e.preventDefault();
        const text = input.value.trim();
        if (!text || sendBtn.disabled) return;
        input.value = "";
        note.textContent = "";
        add("You", text);
        history.push({ role: "user", content: text });
        const thinking = add("AI", "Thinking…");
        sendBtn.disabled = true;
        try {
          const reply = await askAI(history.slice(-20));
          history.push({ role: "assistant", content: reply });
          thinking.querySelector(".text").textContent = reply;
        } catch (err) {
          thinking.remove();
          history.pop();
          note.textContent = err.message;
          if (err.needsKey) showKey(true);
          input.value ||= text;
        } finally { sendBtn.disabled = false; input.focus(); log.scrollTop = log.scrollHeight; }
      };
      openWindow("AI Chat", el, { app: "AI Chat", width: Math.min(560, Math.round(innerWidth * 0.92)), height: appHeight(0.85) });
      setTimeout(() => input.focus(), 50);
    }

    // ======================= Startup =======================
    useLogo(GHETTO_ICON);
    addEye($id("lock-pass"));
    applyCloak();
    applyAppearance();
    showUser();
    tickClock();
    setInterval(tickClock, 1000);
    proxyReady.then(syncAdblock, () => {});
    if (settings.lockOnStart) lockScreen();
    // Already signed in on this device? (Offline: stay a guest with the last saved settings.)
    api("/api/auth/me").then(({ name }) => {
      if (!name) return;
      setAccount(name);
      if (!lockEl.hidden) $id("lock-pass").focus();
      loadAccountPrefs().catch((e) => console.warn("Couldn't load your settings:", e.message));
    }).catch(() => {});
